#include <iostream>
#include <queue>
#include <vector>
using namespace std;

static const int UNVISITED = 0;  // 頂点の訪問状態:未訪問
static const int VISITED = 1;    // 頂点の訪問状態:訪問済み

// 頂点s+1から出発する場合の幅優先探索
void bfs(int s, int n, vector<vector<int>>& M, vector<int>& d) {
    static const int INFTY = (1 << 21);

    // 今回は標準ライブラリのキューを使う
    queue<int> q;
    vector<int> status(n);  // status:頂点の訪問状態
    for (int i = 0; i < n; ++i) {
        status[i] = UNVISITED;
    }

    // 各種初期化処理
    // 出発する頂点をpush
    q.push(s);
    status[s] = VISITED;
    // 距離格納配列の初期化
    for (int i = 0; i < n; ++i) {
        d[i] = INFTY;
    }
    // 出発点の距離は0
    d[s] = 0;

    // 探索開始
    while (!q.empty()) {
        // 先頭を取り出してpopする(訪問)
        int u = q.front();
        q.pop();

        // TODO:
        // uに隣接する頂点で訪問済みでない頂点をキューにpushし、
        // 各頂点の距離を記録する
        for (int v = 0; v < n; ++v) {
            if (M[u][v] == 0) {
                continue;
            }
            if (status[v] == VISITED) {
                continue;
            }
            q.push(v);
            status[v] = VISITED;
            d[v] = d[u] + 1;
        }
    }

    // 頂点1から各頂点までの距離を出力
    // INFTYが入っていた場合は到達不可能なので-1を出力
    for (int i = 0; i < n; ++i) {
        cout << i + 1 << " " << (d[i] == INFTY ? -1 : d[i]) << endl;
    }
}

int main() {
    static const int N = 110;
    // n : グラフの頂点数
    // M : 隣接行列(グラフを表現)
    // d : 任意の頂点から各頂点への距離格納配列(INFTYで初期化)
    int n, u, k, v;
    vector<int> d(N);
    vector<vector<int>> M(N, vector<int>(N));

    cin >> n;

    // グラフの初期化
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            M[i][j] = 0;
        }
    }

    // TODO:
    // 入力を受け取って、隣接行列に反映する
    // (u->vにつながっている場合には、M[u-1][v-1]=1にする)
    for (int i = 0; i < n; ++i) {
        cin >> u >> k;
        for (int j = 0; j < k; ++j) {
            cin >> v;
            M[u - 1][v - 1] = 1;
