	if (argc == 1)
	{
		std::cin.tie(0);
		std::ios::sync_with_stdio(false);
	}

	int num;
	stream >> num;

	int node, degree;
	int t;

	for (int i = 0; i < num; ++i)
	{
		stream >> node >> degree;
		for (int j = 0; j < degree; ++j)
		{
			stream >> t;
			Adj[node - 1][t - 1] = 1;
		}
	}

	Bfs(0, num);

	for (int i = 0; i < num; ++i)
	{
		std::cout << i + 1 << ' ' << 
			((distance[i] == std::numeric_limits<int>::max()) ? -1 : distance[i]) <<
			std::endl;
	}
}

