void enqueue(int x){

  Q[tail] = x;

  if(tail + 1 == 100000) tail = 0;
  else tail++;
}

int dequeue(){

  int x = Q[head];

  if(head + 1 == 100000) head = 0;
  else head++;

  return x;
}

