  enqueue(u);
  d[u] = 0;

  while(head != tail){
    int p = Q[head];
    dequeue();

    for(int i = 2;i <= n;i++){
      //if i is adjoining p and have not been visited, calculate the distance
      if(a[p][i] && d[i] == 0){
        enqueue(i);
        d[i] = d[p] + 1;
      }
    }
  }
}

