void bfs(const int start, vector<vector<int>>& graph,
         vector<int>& dist) {
    queue<int> q; q.push(start); dist[start] = 0;
    while(not q.empty()) {
        auto p = q.front(); q.pop();

        for (auto elm : graph[p]) {
            if(dist[elm] < 0 or dist[elm] > dist[p] + 1) {
