	void operator=(LL n) { minl = min(minl, n); maxl = max(maxl, n); suml += n; cnt++; }
	void operator=(double n) { mind = min(mind, n); maxd = max(maxd, n); sumd += n; cnt++; }
}ans;


const int INF = 1'000'000'000;
const long long INFLL = 1'000'000'000'000'000'000;

using Weight=int;
using P=pair<Weight, int>;
struct Edge { int to; Weight cost; };
using Graph=vector<vector<Edge>>;

void Dijkstra(const Graph& graph, vector<Weight>& dist, int s) {
	int V = graph.size();
	dist.resize(V, INF); dist[s] = 0;

	priority_queue<P, vector<P>, greater<P>> pq;
	pq.push({ 0,s });

	while (!pq.empty()) {
		P p = pq.top(); pq.pop(); int v = p.second;
		if (dist[v] < p.first)continue;
		for (auto e : graph[v]) {
			if (dist[e.to] > dist[v] + e.cost) {
				dist[e.to] = dist[v] + e.cost;
				pq.push({ dist[e.to],e.to });
			}
		}
	}
}

