typedef vector<vector<int>> matrix;

void bfs(matrix G)
{
    int N = G.size() - 1;

    // node[i] = pair<is_visited, int depth>
    vector<pair<bool, int>> node(N + 1, make_pair(false, 0));
    queue<int> Q;

    // initial step
    Q.push(1);
    node[1] = make_pair(true, 0);

    // BFS
    while (!Q.empty())
    {
        int n = Q.front();
        Q.pop();

        int depth = node[n].second;

        for (int i = 1; i <= N; i++)
        {
            bool is_visited = node[i].first;
            bool can_visit = G[n][i];

            if (!is_visited && can_visit)
            {
                Q.push(i);
                node[i] = make_pair(true, depth + 1);
            }
        }
    }

    for (int i = 1; i <= N; i++)
    {
        if (node[i].first == false)
        {
            cout << i << " " << -1 << endl;
        }
        else
        {
            cout << i << " " << node[i].second << endl;
        }
    }
    return;
}

