int BFS(int s, int t, const vector<vector<int> >& G){
    vector<int> stock1;
    vector<int> stock2;
    vector<int> *s1p = &stock1;
    vector<int> *s2p = &stock2;
    stock1.push_back(s);
    int d = 0;
    while (1) {
        for (int i = 0; i < s1p->size(); i++) {
            if ((*s1p)[i] == t) return d;
            for (int j = 0; j < G[(*s1p)[i]].size(); j++) {
                s2p->push_back(G[(*s1p)[i]][j]);
            }
        }
        if (s1p == &stock1) {
            s1p = &stock2;
            s2p = &stock1;
        } else {
            s1p = &stock1;
            s2p = &stock2;
        }
        d++;
    }
}

