void bfs(int s) {
    queue<int> q;
    q.push(s);
    for ( int i = 0; i < n; i++ ) d[i] = INFTY;
    d[s] = 0;
    int u;
    while ( !q.empty() ) {
        u = q.front(); q.pop();   //front:キューから取り出し、pop:キューから削除
        for ( int v = 0; v < n; v++ ) {
