            if ( d[v] != INFTY ) continue;   //頂点を訪れたか確認
            d[v] = d[u] + 1;   //始点からの距離を格納
            q.push(v);   //次に調査する頂点をキューに追加
        }
    }
    for ( int i = 0; i < n; i++ ) {
        cout << i+1 << " " << ( (d[i] == INFTY) ? (-1) : d[i] ) << endl;
    }
}

