//根である1から子に対して、根の数値を加算していく作業を一回だけ行えば条件は満たされる

void DFS(const Graph &G,int v,vector<bool> &seen,vector<int> &counter){//深さ優先探索。
//引数は順にグラフ、始点(注目点)、探索済みかどうか、各点の持つ値を記録するカウンタ

  seen[v]=true;

  for(auto next_v : G[v]){
    if(seen[next_v]) continue;
    counter[next_v]+=counter[v];
    DFS(G,next_v,seen,counter);
  }

  return ;

}


