void solve() {
    int n;
    cin >> n;
    vector<vector<int>> g(n, vector<int>());
    int u, k;
    REP(i, n) {
        cin >> u >> k;
        u--;
        int v;
        REP(j, k) {
            cin >> v;
            v--;
            g[u].emplace_back(v);
        }
    }

    deque<pair<int, int>> q;
    q.emplace_back(0, 0);

    vector<int> ans(n, -1);
    while (!q.empty()) {
        auto p = q.front(); q.pop_front();
        if (ans[p.first] == -1) ans[p.first] = p.second;

        for (auto r : g[p.first]) {
            if (ans[r] != -1) continue;
            q.emplace_back(r, p.second + 1);
        }
    }
    REP(i, n) cout << i + 1 << " " << ans[i] << endl;
}

