using namespace std;

class Queue{
private:
  int inf[MAX];
  int head,tail;

public:

  Queue(){
    syokika();
  }

  void syokika(){
    head = 0;
    tail = 0;
  }

  void push(int x){
    inf[tail]=x;
    if(MAX == tail+1)tail = 0;
    else tail++;
  }

  void pop(){
    if(MAX == head+1)head=0;
    else head++;
  }

  int front(){
    return inf[head];
  }

  bool empty(){
    if(tail - head == 0)return true;
    else return false;
  }

  int size(){
    return tail - head;
  }

};

