int n;
int far[maxn + 5];


int bfs(int vertex) {
    queue<int> q;
    int book[maxn + 5] = {};
    q.push(vertex);
    book[vertex] = 1;
    int min = 0;
    if(vertex == 1) return 0;

    while(!q.empty()) {
        int now = q.front();
        q.pop();

        int len = G[now].size();
        for(int i = 0; i < len; i++) {
            if(book[G[now][i]]) continue;

            if(G[now][i] == 1) return min + 1;

            book[G[now][i]] = 1;
            q.push(G[now][i]);
        }
        min++;
    }
    return -1;
}



