int main() {
    int N;
    cin>>N;
    vector<vector<int> > graph(N);
    int u, k, tmp;
    for(int i=0;i<N;++i){
        cin>>u>>k;
        for(int j=0;j<k;++j){
            cin>>tmp;
            tmp--;
            graph[i].push_back(tmp);
        }
    }
    queue<int> que;
    queue<int> passque;
    que.push(0);
    passque.push(0);
    int node, pass;
    vector<int> ans(N);
    for(int i=0;i<N;++i){
        ans[i] = -1;
    }
    map<int, int> past;
    past[0]++;
    while(!que.empty()){
        node = que.front();que.pop();
        pass = passque.front();passque.pop();
        ans[node] = pass;
        for(int i=0;i<graph[node].size();++i){
            if(past[graph[node][i]]==0){
                que.push(graph[node][i]);
                passque.push(pass + 1);
            }
            past[graph[node][i]]++;
        }
    }
    for(int i=0;i<N;++i){
        cout<<i+1<<" "<<ans[i]<<endl;
