const int kSize = 101;

vector<int> adj[kSize];
bool isMarked[kSize];
int d[kSize];

void dfs(int v) {
    isMarked[v] = true;

    for (int i = 0; i < adj[v].size(); ++i) {
        int u = adj[v][i];
        if (!isMarked[u]) {
            dfs(u);
        }
    }
}

void bfs() {
    queue<int> q;
    q.push(1);
    d[1] = 0;
    int dis = 0;
    isMarked[1] = true;

    while (!q.empty()) {
        int size = q.size();
        for (int i = 0; i < size; ++i) {
            int u = q.front();
            q.pop();
            for (int j = 0; j < adj[u].size(); ++j) {
                int v = adj[u][j];
                if (!isMarked[v]) {
                    q.push(v);
                    isMarked[v] = true;
                }
            }

            d[u] = dis;
        }

        dis++;
    }
}

