class TNode
{
	int FIndex;
	std::list<TNode*> FTarget;
public:
	TNode(int Index)
	: FIndex(Index)
	{
	}

	void Push(TNode* New)
	{
		FTarget.push_back(New);
	}

	int Distance(const TNode* Target)const
	{
		if(Target == this) return 0;
		if(std::find(FTarget.begin(), FTarget.end(), Target) != FTarget.end()) return 1;
		int Minimum = -1;
		for(std::list<TNode*>::const_iterator It = FTarget.begin(); It != FTarget.end(); ++It){
			int Distance = (*It)->Distance(Target);
			if(Distance >= 0 && (Minimum > Distance || Minimum < 0)){
				Minimum = Distance;
			}
		}
		return 1 + Minimum;
	}
};

class TGraph
{
	std::vector<TNode*> FNodes;
public:
	TGraph(int Count)
	: FNodes(Count)
	{
		for(int i = 0; i < Count; ++i){
			FNodes[i] = new TNode(i + 1);
		}
	}

	~TGraph()
	{
		for(unsigned int i = 0; i < FNodes.size(); ++i){
			delete FNodes[i];
		}
	}

	void InputNode()
	{
		int Index;
		std::cin >> Index;
		int BranchCount;
		std::cin >> BranchCount;
		for(int i = 0; i < BranchCount; ++i){
			int Target;
			std::cin >> Target;
			FNodes[Index - 1]->Push(FNodes[Target - 1]);
		}
	}

	int MeasureDistance(int Start, int End)const
	{
		return FNodes[Start - 1]->Distance(FNodes[End - 1]);
	}
};

