int bfs(int n,vector<vector<int>>& A,int v,vector<int>& d,vector<int>& flag){
        d[v]=0;
        flag[v]=1;
        queue<int> Q;
        for(int i=0;i<n;i++){if(A[v][i]==1){Q.push(i);}}
        int dmin;
        while(!Q.empty()){
                dmin=INF;
                for(int i=0;i<n;i++){if(A[i][Q.front()]==1 && d[i]<dmin){dmin=d[i];}}
                d[Q.front()]=dmin+1;
                flag[Q.front()]=1;
                for(int i=0;i<n;i++){if(A[Q.front()][i]==1 && flag[i]!=1){Q.push(i);}}
                Q.pop();
        }
}

