struct Q {
    int to, depth;
};

void bfs(int from, vector<vector<int>> &tos, set<int> &used, vector<int> &ans) {
    queue<Q> q;
    q.push({from, 0});

    while (!q.empty()) {
        Q top = q.front();
        q.pop();
        if (!contain(used, top.to)) {
            continue;
        }

        used.erase(top.to);
        ans[top.to] = top.depth;

        for (int to : tos[top.to]) {
            q.push({to, top.depth + 1});
        }
    }

}

