vector<int> bfs(int src, Matrix &M) {
    int n = M.size();
    vector<int> dist(n, -1);
    queue<int> Q;
    dist[src] = 0;
    Q.push(src);
    while (!Q.empty()) {
        int cur = Q.front(); Q.pop();
        for (int nxt = 0; nxt < n; nxt++) {
            if (M[cur][nxt] && dist[nxt] < 0) {
                dist[nxt] = dist[cur] + 1;
                Q.push(nxt);
            }
        }
    }
    return dist;
}

