using namespace std;

int n;
int arr[100][100];
int time_saver[100][2];
int now_time;
queue< pair < int, int > > q;

void search(int fi, int fnow_time){
    time_saver[fi][0] = fnow_time;
    for(int i=0; i<100; i++){
        if(arr[fi][i] && !time_saver[arr[fi][i]-1][0]){
            int a = fnow_time+1;
            q.push(make_pair(arr[fi][i]-1, a));
        }
    }
}

int main(int argc, const char * argv[]) {

    /////////
    //write//
    /////////

    cin >> n;
    now_time = 0;
    for(int i=0; i<100; i++){
        for(int j=0; j<100; j++){
            arr[i][j] = 0;
        }
        for(int j=0; j<2; j++){
            time_saver[i][j] = 0;
        }
    }

    for(int i=0; i<n; i++){
        int node, degree; cin >> node >> degree;
        for(int j=0; j<degree; j++){
            int tmp; cin >> tmp;
            arr[node-1][tmp-1] = tmp;
        }
    }

    for(int i=0; i<1; i++){
        if(time_saver[i][0])continue;
        search(i, now_time);
        while(!q.empty()){
            int tmp = q.front().first;
            int tmp2 = q.front().second;
            now_time = max(now_time, q.front().second+1);
            q.pop();
            if(time_saver[tmp][0] || tmp == 0)continue;
            search(tmp, tmp2);
        }
    }
    for(int i=1; i<n; i++){
        if(!time_saver[i][0])time_saver[i][0] = -1;
    }

    for(int i=0; i<n; i++){
        for(int j=0; j<1; j++){
            if(j)cout << " ";
            else cout << i+1 << " ";
            cout << time_saver[i][j];
        }
        cout << endl;
    }

    return 0;
}

