using namespace std;

int G[101][101];
int d[101];

void explore(int id, int n,int cnt)
{
	if (cnt == n)
	{
		return;
	}
	if (d[id] == -1)
	{
		d[id] = cnt;
	}
	else
	{
		d[id] = min(d[id], cnt);
	}

	for (int i = 1; i <= n; i++)
	{
		if (G[id][i] == 1)
		{
			explore(i, n, cnt + 1);
		}
	}
}

