vector<int> seen;
vector<int> done;
vector<int> cost;
int timestamp;

// Graph: グラフを表した隣接リスト
// v: 何番目のノードを訪問するのか
void dfs(vector<vector<int> > &Graph, int v){
    timestamp++;
    seen[v] = timestamp; //訪問済みにする

    // 隣接するノードを再帰的に訪問
    for(int next_v = 0; next_v < Graph[v].size();next_v++) {
        if(seen[Graph[v][next_v]] != -1) continue;
        dfs(Graph, Graph[v][next_v]);
    }
    // 出るときの時間が増える
    timestamp++;
    done[v] = timestamp; // 隣接ノードを全て調べ終えた
}

queue<int> que;
vector<long> dist;
// v: 何番目の頂点を訪問しているのか
void bfd(vector<vector<int> > &Graph, int v){
    done[v] = timestamp;

    for(int next_v = 0; next_v < Graph[v].size();next_v++){
        if(seen[Graph[v][next_v]] == -1){
            dist[Graph[v][next_v]] = dist[v] + 1;
            seen[Graph[v][next_v]] = timestamp;
            que.push(Graph[v][next_v]);
        }else{
            dist[Graph[v][next_v]] = min(dist[Graph[v][next_v]], dist[v] + 1);
        }
    }
}

