int inf = 1000000000;

class Graph{
public:
  int v;
  int cost = inf;
  int ftime = -1;
  int ltime = -1;
  vector<int> e;
};
vector<Graph> g;
int cnt = 0;
void dfs(int pos){
  if( g[pos].ftime != -1 ) return;
  cnt++;
  g[pos].ftime = cnt;
  for(int i=0; i<g[pos].e.size(); i++){
    dfs(g[pos].e[i]);
  }
  cnt++;
  g[pos].ltime = cnt;
}
void bfs(int pos){
  for(int i=0; i<g[pos].e.size(); i++){
    // if( g[ g[pos].e[i] ].cost != inf ) continue;
    g[ g[pos].e[i] ].cost = min(g[ g[pos].e[i] ].cost, g[pos].cost + 1);
    bfs(g[pos].e[i]);
  }
}

