using namespace std;

// 辺を表す構造体
struct edge{
    int to, cost;
};

// キューに入れる頂点を表す構造体
struct node{
    int id, cost;
};

constexpr int INF = (1 << 30) - 1;

// s:=始点 cost:=始点からの最短経路長がここに書き込まれる g:=隣接リストでグラフを渡す
void breadth_first_search(int s, vector<int>& cost, const vector< vector<edge> >& g){
    cost.resize(g.size());
    fill(cost.begin(), cost.end(), INF);
    cost[s] = 0;
    queue<node> que;
    que.push({s, 0});

    while(!que.empty()){
        node now = que.front();
        que.pop();
        if(cost[now.id] < now.cost){
            continue;
        }
        for(auto& e : g[now.id]){
            if(cost[e.to] > now.cost + e.cost){
                cost[e.to] = now.cost + e.cost;
                que.push({e.to, now.cost + e.cost});
            }
        }
    }

    return;
}

int main(){
    int n;
    cin >> n;

    vector< vector<edge> > g(n);
    for(int i = 0 ; i < n ; ++i){
        int u, k;
        cin >> u >> k;
        --u;
        for(int j = 0 ; j < k ; ++j){
            int v;
            cin >> v;
            g[u].push_back({--v, 1});
        }
    }

    vector<int> cost;
    breadth_first_search(0, cost, g);

    for(int i = 0 ; i < n ; ++i){
        cout << i + 1 << " ";
        if(cost[i] < INF){
            cout << cost[i] << endl;
        }else{
            cout << -1 << endl;
        }
    }

    return 0;
}

