int N;
int M[101][101];
queue<int> que;
int cost[101];

void solve(int now){
	for(int i=0; i<N; i++){
		if(M[now][i] == 1){
			if(cost[i] == -1){
				cost[i] = cost[now] + 1;
				que.push(i);
			}
			else if(cost[now] + 1 < cost[i]){
				cost[i] = cost[now] + 1;
				que.push(i);
			}
		}
	}
}

