	for(int i=0; i<N; i++){
		cost[i] = -1;
	}

	cost[0] = 0;
	que.push(0);
	while (!que.empty())
	{
		solve(que.front());
		que.pop();
	}

	for(int i=0; i<N; i++){
		cout << i+1 << " " << cost[i] << endl;
	}

	return 0;
}

