    visits.push(0);
    while(! visits.empty()) {
        int id = visits.front();
        visits.pop();
        vector<int> adjs = graph[id];
        for (int i = 0; i < adjs.size(); i++) {
            int adj = adjs[i];
            if (! found[adj]) {
                found[adj] = 1;
                paths[adj] = paths[id] + 1;
                visits.push(adj);
            }
        }
    }

    // 辿りつけなかった頂点までの距離は -1 とする。
    for (int i = 1; i < n_v; i++) {
        if (paths[i] == 0) {
            paths[i] = -1;
        }
    }
}

