void BFS(vector<vector<int> > A, vector<int> &d, vector<int> &visit, int v){
	if(v == 0){
		d[0] = 0;
		visit[0] = 1;
	}

	for(int i=0;i<A[v].size();i++){
		if((A[v][i] == 1) && (d[i] > d[v]+1)){
			d[i] = d[v]+1;
			visit[i] = 1;
			BFS(A, d, visit, i);
		}
	}	
}

