#define N 101

void BreadthFirstSearch();

class queue{
public:
    int array[100];
    int head = -1;
    int tail = -1;

    void push(int v) {
        tail = (tail + 1) % N;
        array[tail] = v;
        return;
    }

    int pop() {
        head = (head + 1) % N;
        return array[head];
    }

    int show() {
        return array[head];
    }

    bool empty() {
        if(head == tail) return true;
        else return false;
    }
};

