void BreadthFirstSearch() {
    int u = q.pop();
    int i = 0;

    while(a[u][i] != 0) {
        if(list[ a[u][i] ] != -1) {
            i++;
            continue;
        }
        q.push(a[u][i]);
        list[ a[u][i] ] = list[u] + 1;
        i++;
    }
}

