void Breadth_First_Search(void){
    while(!Number_of_vertices.empty()){
        int u = Number_of_vertices.front();
        Number_of_vertices.pop();
        for(int i=0;i<n;i++){
            if(color[i]==0 && A[u][i]==1){
                d[i] = d[u] + 1;
                color[i] = 1;
                Number_of_vertices.push(i);
            }
        }
    }
}
