	void BreadthFirstSearch();

};

Graph::Graph(int n){
	A.resize(n);
	d.resize(n);
	for (int i = 0; i < n; i++){
		A[i].resize(n);
		for (int j = 0; j < n; j++){
			A[i][j] = 0;
		}
		d[i] = -1;
	}
	this->n = n;
}

void Graph::BreadthFirstSearch(){
	d[0] = 0;
	std::vector<int> a(2, 0);
	a[1] = 1;
	Q.push_back(a);
	while (!Q.empty()){
		std::vector<int> f = Q.front();
		Q.pop_front();
		for (int i = 0; i < n; i++){
			if (A[f[0]][i] == 1 && d[i] == -1){
				d[i] = f[1];
				a[0] = i;
				a[1] = f[1] + 1;
				Q.push_back(a);
			}
		}
	}
	return;
}

