int N;

vector<vector<int>> G;

vector<int> bfs(int start)
{
    vector<int> d(N, INF);
    queue<int> que;
    d[start] = 0;
    que.emplace(start);

    while(!que.empty()) {
        int v = POP(que);

        for(int to : G[v]) {
            if(d[to] != INF) continue;
            d[to] = d[v] + 1;
            que.emplace(to);
        }
    }

    return d;
}

void solve()
{
    vector<int> d = bfs(0);

    REP(i, N) {
        PRINTLN(i+1, d[i] == INF ? -1 : d[i]);
    }
}

signed main(signed /*argc*/, char** /*argv*/)
{
    RD(N);
    G.resize(N);

    REP(_, N) {
        int u; RD(u); --u; // 0-based
        int k; RD(k);
        G[u].resize(k);
        REP(i, k) {
            int v; RD(v); --v; // 0-based
            G[u][i] = v;
        }
    }

    solve();

    EXIT();
}

#include <iostream>
#include <vector>
#include <list>
#include <cstdlib>

const int MAX_N = 100;

struct Node {
  int v;
  int d;
  bool visited;
};

int main(void) {
  std::cin.tie(0);
  std::ios::sync_with_stdio(false);  

  int n = 0;
  std::cin >> n;

  std::vector<std::vector<int> *> *graph = new std::vector<std::vector<int> *>(n + 1);
  std::vector<struct Node *> *nodes = new std::vector<struct Node *>(n + 1);

  for (int i = 1; i <= n; i++) {
    int v = 0;
    std::cin >> v;

    int k = 0;
    std::cin >> k;

    std::vector<int> *neighbors = new std::vector<int>(k);

    for (int i = 0; i < k; i++) {
      int a = 0;
      std::cin >> a;

      neighbors->at(i) = a;
    }

    graph->at(i) = neighbors;

    struct Node *node = (struct Node *) std::malloc(sizeof(struct Node));

    node->v = i;
    node->d = -1;
    node->visited = false;

    nodes->at(i) = node;
  }

  int count = 0;
  int start = 1;

  //  nodes->at(start)->d = 1;

  std::list<int> *stack = new std::list<int>();

  stack->push_back(nodes->at(start)->v);

  while (!stack->empty()) {
    std::vector<int> *newNodes = new std::vector<int>();

    while (!stack->empty()) {    
      int v = stack->front();
      stack->pop_front();

      nodes->at(v)->d = count;
      nodes->at(v)->visited = true;

      std::vector<int> *neighbors = graph->at(v);

      for (std::vector<int>::iterator iterator = neighbors->begin(); iterator != neighbors->end(); ++iterator) {
	struct Node *node = nodes->at(*iterator);

	if (!node->visited) {
	  newNodes->push_back(node->v);
	}
      }
    }

    for (std::vector<int>::iterator iterator = newNodes->begin(); iterator != newNodes->end(); ++iterator) {
      stack->push_front(*iterator);
    }

    count++;
  }

  for (std::vector<struct Node *>::iterator iterator = nodes->begin() + 1; iterator != nodes->end(); ++iterator) {
    struct Node *node = *iterator;

    std::cout << node->v << " " << node->d << std::endl;
  }

  return 0;
}

#include <iostream>
