using namespace std;
static const int MAX = 100;
static const int WHITE = 0;
static const int GRAY = 1;
static const int BLACK = 2;
static const int NIL = -1;
int M[MAX][MAX], n;
int d[MAX], color[MAX];
queue<int> Q;

void bfs(int s)
{
    int u, v;
    Q.push(s);
    color[s] = GRAY;
    d[s] = 0;
    while (!Q.empty())
    {
        u = Q.front();
        Q.pop();
        for (int v = 0; v != n; ++v)
        {
            if (M[u][v] && color[v] == WHITE)
            {
                Q.push(v);
                color[v] = GRAY;
                d[v] = d[u] + 1;
            }
        }
        color[u] = BLACK;
    }
}

