#include <bits/stdc++.h>
using namespace std;
#define WHITE 0
#define GLAY 1

// 頂点の個数
int n;
// 隣接行列
vector<vector<int> > M(100, vector<int>(100));
// 頂点の深さを格納する配列
vector<int> D(100, -1);
// 頂点の状態を格納する配列
vector<int> color(100, WHITE);
// 訪問すべき頂点を格納するキュー
queue<int> Q;

void bfs()
{
  // 初期化
  Q.push(0);
  D.at(0) = 0;
  while (!Q.empty())
  {
    // 未訪問の頂点が残っているとき
    int u = Q.front();
    Q.pop();
    color.at(u) = GLAY;
    for (int v = 0; v < n; v++)
    {
      if (M.at(u).at(v) == 1 && color.at(v) == WHITE && D.at(v) == -1)
      {
        // vはuから直接訪問でき、かつ未訪問の頂点、かつ深さ未設定のとき
        Q.push(v);
        D.at(v) = D.at(u) + 1;
      }
    }
  }
}

int main()
{
  cin >> n;
  for (int i = 0; i < n; i++)
  {
    int u, k;
    cin >> u >> k;
    u--;
    for (int j = 0; j < k; j++)
    {
      int v;
      cin >> v;
      v--;
      M.at(u).at(v) = 1;
    }
  }

  bfs();

  for (int i = 0; i < n; i++)
  {
    cout << i + 1 << " " << D.at(i) << endl;
  }
}

#include <iostream>
#include <queue>
#include <assert.h>
#define INF 100000000
#define MAX_V 100
using namespace std;

int adjacencyMatrix[MAX_V][MAX_V] = {};
int d[MAX_V];
int V;

void bfs(int start)
{
    queue<int> Q;
    Q.push(start);

    for (int i = 0; i < V; ++i)
        d[i] = INF;

    d[start] = 0;

    while (!Q.empty()) {
        int u = Q.front();
        Q.pop();
        for (int i = 0; i < V; ++i) {
            if (d[i] != INF) continue;
            if (adjacencyMatrix[u][i] == 1)
                d[i] = d[u] + 1;
            Q.push(i);
        }
    }
    return;
}

int main()
{
    cin >> V;

    for (int i = 0; i < V; ++i) {
        int u, k;
        cin >> u >> k;
        assert(u = i + 1);
        for (int j = 0; j < k; ++j) {
            int tmp;
            cin >> tmp;
            adjacencyMatrix[i][tmp - 1] = 1;
        }
    }

    bfs(0);

    for (int i = 0; i < V; ++i)
        cout << i + 1 << " " << d[i] << endl;

    return 0;
}

