            G.lst[i][j] = v;
        }
    }

    graph GG = bfs(G, 0);
    for (int i = 0; i < n; i++) {
        std::cout << i + 1 << " "
                  << ((GG.vs[i].d == graph::inf)
                      ? -1 : GG.vs[i].d) << std::endl;
    }
    return 0;
}

