        for (int j = 0; j < k; ++j) {
            int sv;
            cin >> sv;
            graph.span(v, --sv);
        }
    }

    auto dist = bfs<int>(graph, 0);
    for (int v = 0; v < N; ++v) {
        cout << v + 1 << " " << dist[v] << endl;
    }
    return 0;
}

