struct Tree
{
    int p, start, end, min;
    bool isSearched;
    vector<int> v;
};

void DFS( Tree* t, int a, int cnt )
{
    if( t[a].isSearched && t[a].min <= cnt )
        return;

    t[a].isSearched = true;

    if( t[a].min > cnt )
        t[a].min = cnt;

    cnt++;

    for( int i = 0; i < t[a].v.size(); i++ )
        DFS( t, t[a].v[i], cnt );
}


