#include<bits/stdc++.h>
using namespace std;
static const int INF=(1<<21);
int n,M[111][111];
int d[111]; //最短距離を記録（到達不可な時はINF）
void bfs(int s){
  queue<int>q;
  q.push(s); //始点INFを入れる（訪問）
  for(int i=0;i<n;i++) d[i]=INF; //あらかじめINFを入れておく
  d[s]=0;
  while(!q.empty()){
    int u=q.front();
    q.pop(); //キューから頂点uを取り出し訪問
    for(int v=0;v<n;v++){
      if(M[u][v]==0) continue; //辺がない
      if(d[v]!=INF) continue; //訪問したことがある
      d[v]=d[u]+1; //vは未訪問の頂点であり、隣接しているためd[u]に1を足す
      q.push(v); //vを始点に
    }
  }
  for(int i=0;i<n;i++){
    cout<<i+1<<' '<<( (d[i]==INF)?(-1):d[i] )<<endl;
  }
}
