vector<vector<int>> GetAdjacencyMatrix(int n)
{
	vector<vector<int>> am(n, vector<int>(n));
	for (int i = 0; i < n; i++) {
		int u, k;
		cin >> u >> k;
		u--;
		for (int j = 0; j < k; j++) {
			int v;
			cin >> v;
			am[u][--v] = 1;
		}
	}
	return am;
}

void BFS(int startNode, int n, const vector<vector<int>>& am, vector<int>& minDistances)
{
	queue<int> q;
	q.push(startNode);
	while (!q.empty()) {
		int node = q.front();
		q.pop();
		for (int i = 0; i < n; i++) {
			if (am[node][i] == 0) continue;
			if (minDistances[i] != INF) continue;
			q.push(i);
			int distance = minDistances[node] + 1;
			minDistances[i] = min(minDistances[i], distance);
		}
	}
}

