const int nIMPOS = -1;
struct StDir
{
  int m_nx;
  int m_nEtc;

  StDir(int nx) : m_nx(nx), m_nEtc(0)
  { }
};

void fnInput(vector<vector<int>>& rvvnAdjcy, vector<int>& rvnDst)
{
  int nxSiz;
  cin >> nxSiz;

  rvvnAdjcy.resize(nxSiz + 1, vector<int>(nxSiz + 1, 0));
  for (int i = 0; i < nxSiz; ++i)
  {
    int nx, nySiz;
    cin >> nx >> nySiz;
    for (int j = 0; j < nySiz; ++j)
    {
      int ny;
      cin >> ny;
      rvvnAdjcy[nx][ny] = 1;
    }
  }
  rvnDst.resize(nxSiz + 1, nIMPOS);
}

void fnBreadthFirstSearch(const vector<vector<int>>& cnrvvnAdjcy, 
                          queue<StDir>& rqoBFSrch, vector<int>& rvnDst)
{
  while (rqoBFSrch.size())
  {
    StDir oDir = rqoBFSrch.front(); rqoBFSrch.pop();
    if (rvnDst[oDir.m_nx] == nIMPOS)  continue;

    for (int ny = 1; ny < cnrvvnAdjcy[oDir.m_nx].size(); ++ny)
      if (cnrvvnAdjcy[oDir.m_nx][ny] == 1)
      {
        int nDst = rvnDst[oDir.m_nx] + 1;
        if (rvnDst[ny] == nIMPOS)
          rvnDst[ny] = nDst;
        else
          rvnDst[ny] = min(rvnDst[ny], nDst);

        StDir oDir(ny);
        rqoBFSrch.push(oDir);
      }
  }
}

void fnResult(const vector<int>& cnrvnDst)
{
  for (int i = 1; i < cnrvnDst.size(); ++i)
    cout << i <<  " " << cnrvnDst[i] << endl;
}

int main()
{
  cin.tie(0);
  ios::sync_with_stdio(false);
  vector<vector<int>> vvnAdjcy;
  queue<StDir> qoBFSrch;
  vector<int>  vnDst;

  fnInput(vvnAdjcy, vnDst);

  vnDst[1] = 0;
  StDir oDir(1);
  qoBFSrch.push(oDir);
  fnBreadthFirstSearch(vvnAdjcy, qoBFSrch, vnDst);
  fnResult(vnDst);

  return 0;
}

