#include <stdio.h>
#include <stdlib.h>

struct node_t {
	int key;
	struct node_t *next;
};
typedef struct node_t Node;

Node *enqueue(Node *node, int key) {
	Node *p, *q;

	if (node == NULL) {
		node = malloc(sizeof(Node));
		node->key = key;
		node->next = NULL;
		return node;
	}

	for (p = node; p != NULL; p = p->next) {
		q = p;
	}
	q->next = malloc(sizeof(Node));
	q->next->key = key;
	q->next->next = NULL;
	return node;
}

Node *dequeue(Node *node, int *key) {
	Node *p;

	if (node != NULL) {
		*key = node->key;
		p = node->next;
		free(node);
		return p;
	}
	return NULL;
}

