void search(int **a, int n, int *d, int u, int t) {
  if(t > n) return;
  int i;
  if(d[u] == 0 || d[u] > t) d[u] = t;
  for (i = 1; i < n; i++) {
    if(a[u][i] == 1) {
      search(a,n,d,i,t+1);
    }
  }
}

