    scanf("%d %d", &node, &k);
    for(j = 0;j < k;j++) {
      scanf("%d", &direction);
      graph[node].is_connected_to[direction] = true;
    }
  }

  graph[1].distance = 0;
  breadthSearch(1);

  for(i = 1;i < n + 1;i++) {
    printf("%d %d\n", i, graph[i].distance);
  }
