#define VERTEX_MAX 100

static int start = 0;
static int end = 0;
int queue[VERTEX_MAX+1];

void enqueue(int v) {
    queue[end++] = v;
}

int dequeue(void) {
    return queue[start++];
}

int is_empty(void) {
    return start == end;
}

int main(void) {
    int vs = get_int();
    int i, j;
    int buf[VERTEX_MAX];
    static int map[VERTEX_MAX+1][VERTEX_MAX+1];
    for(i = 0; i < vs; i++) {
        int size, id;
        fget_array(buf, &size, &id);
        for(j = 0; j < size; j++) {
            // directed graph
            map[id][buf[j]] = 1;
        }
    }

    int dist[VERTEX_MAX+1];
    for(i = 1; i <= vs; i++) {
        dist[i] = -1;
    }

    int start = 1; int steps = 0;
    int nv;
    // we can merge dist variable, but simple is best choice.
    int checked[VERTEX_MAX+1] = {0};
    enqueue(start);
    checked[start] = 1; dist[start] = steps;
    while(!is_empty()) {
        int v = dequeue();
        steps++;
        for(nv = 1; nv <= vs; nv++) {
            if(map[v][nv] && !checked[nv]) {
                dist[nv] = dist[v] + 1;
                checked[nv] = 1;
                enqueue(nv);
            }
        }
    }

    for(i = 1; i <= vs; i++) {
        printf("%d %d\n", i, dist[i]);
    }
    return 0;
}

