int empty() { return head == tail; }
int push(int elm) { que[tail] = elm; tail = (tail+1)%SIZE; }
int front() { return que[head]; }
void pop() { head = (head+1)%SIZE; }

int bfs(int n, int G[][101], int *cost) {
  int i;
  init();
  push(1);
  cost[1] = 0;
  while(!empty()) {
    int p = front();
    pop();
    for(i = 1; i <= n; ++i) {
      if(!G[p][i]) continue;
      if(cost[i] != -1) continue;
      cost[i] = cost[p] + G[p][i];
      push(i);
    }
  }
}


