void width(int st){
  int i;
  int max[N];
  int s=0,g=0;

  max[g]=st;
  ++g;

  while(1){
    if(s==g) break;

    st=max[s];
    ++s;

    for(i=1;i<=n;i++){
      if(hi[st][i]==1){
	if(distance[i]>=0)
	  continue;
	max[g]=i;
	++g;

	distance[i]=distance[st]+1;
      }
    }
  }
}

