typedef struct EDGE {
	int to;
	struct EDGE *next;
} edge;

int size;
edge buff[MAX_M];
edge *adj[MAX_N];

void add_edge(int u, int v) {
	edge *e = buff + size++;
	e->to = v;
	e->next = adj[u];
	adj[u] = e;
}

typedef int data_t;
data_t queue[MAX_N];
int head, tail;

void enqueue(data_t data) {
	queue[tail++] = data;
}

data_t dequeue() {
	return queue[head++];
}

bool empty() {
	return head == tail;
}

int dist[MAX_N];

void bfs(int s) {
	edge *e;

	memset(dist, -1, sizeof(dist));
	dist[s] = 0;
	enqueue(s);

	while(!empty()) {
		const int u = dequeue();
		for(e = adj[u]; e != NULL; e = e->next) {
			if(dist[e->to] == -1) {
				dist[e->to] = dist[u] + 1;
				enqueue(e->to);
			}
		}
	}
}

