void walk(int k, int d)
{
  int i, j;
  for (j=0; j<kk[k]; j++) {
    i = ((int*)vv[k])[j]-1;
    if (dist[i]<0 || (dist[i]>0 && dist[i]>d))
      dist[i] = d;
    else continue;
    walk(i, d+1);
  }
}

