void enq( int data ){

    if( tail == M )  tail = 0;
    Q[tail] = data;
    tail++;

    return ;
}

int deq( void ){
    int retval;

    if( head == M ){
	head = 0;
	retval = Q[head];
	head++;
    }
    else {
	head++;
	retval = Q[head-1];
    }

    return retval;
}

