	enqueue(s);

	while(!empty()) {
		const int u = dequeue();
		for(e = adj[u]; e != NULL; e = e->next) {
			if(dist[e->to] == -1) {
				dist[e->to] = dist[u] + 1;
				enqueue(e->to);
			}
		}
	}
}

