}

void BFS( int table[], int s, int n )
{
    int u, v;

    ENQ( s - 1 );
    while( !isemp() ) {
        u = DEQ();
        if ( step[u] == -1 )
            step[u] = 0;

        for( v=0; v<n; ++v ) {
            if ( table[u*N+v] == 1 && step[v] == -1 ) {
                step[v] = step[u] + 1;
                ENQ( v );
            }
        }
    }
}

