void AdjacencyMatrices(int x,int y)
{
  int i;

  for(i = 1;i <= n;i++){
    if(g[x].v[y] == i) a[x][i] += 1;
    else a[x][i] += 0;
  }
}

void BreadthFirstSearch()
{
  int i,j;

  for(i = 1;i <= n;i++){
    if(a[1][i] == 1) g[i].path = 1;
  }

  for(i = 2;i <= n;i++){
    for(j = 1;j <= n;j++){
      if(a[i][j] == 1 && a[1][j] == 0) g[j].path = g[i].path + 1;
    }
  }
}

