G g;
int upe(const void *a, const void *b){
    if(((E*)a)->fr != ((E*)b)->fr) 
        return (((E*)a)->fr > ((E*)b)->fr ? 1 : -1);
    else
        return (((E*)a)->to == ((E*)b)->to ? 0 : (((E*)a)->to > ((E*)b)->to ? 1 : -1));
}
void g_init(int vn, int en){
    int a, b, u;
    rep(i, vn) g.siz[i] = 0;
    rep(i, vn) {
        scanf("%d%d", &a, &u);
        a--;
        g.siz[a] = u;
        rep(j, u) {
            scanf("%d", &b);
            b--;
            g.e[en].fr = a; g.e[en].to = b;
            en++;
        }
    }
    qsort(g.e, en, sizeof(E), upe);
    g.st[0] = 0;
    rep(i, vn-1){
        g.st[i+1] = g.st[i] + g.siz[i];
    }
}

