    ((type *)(__mptr - offsetof(type, member))); })
//


// List
struct list_head {
    struct list_head *next, *prev;
};

static inline void INIT_LIST_HEAD(struct list_head *list) {
    list->next = list;
    list->prev = list;
}

static inline void __list_add(struct list_head *new, struct list_head *prev, struct list_head *next) {
    next->prev = new;
    new->next = next;
    new->prev = prev;
    prev->next = new;
}

static inline void list_add(struct list_head *new, struct list_head *head) {
    __list_add(new, head, head->next);
}

static inline void list_add_tail(struct list_head *new, struct list_head *head) {
    __list_add(new, head->prev, head);
}

static inline void __list_del(struct list_head *prev, struct list_head *next) {
    next->prev = prev;
    prev->next = next;
}

static inline void __list_del_entry(struct list_head *entry) {
    __list_del(entry->prev, entry->next);
}

static inline void list_del(struct list_head *entry) {
    __list_del_entry(entry);
    entry->next = NULL;
    entry->prev = NULL;
}

static inline int list_empty(const struct list_head *head) {
    return head->next == head;
}

#define list_entry(ptr, type, member) container_of(ptr, type, member)
#define list_first_entry(ptr, type, member) list_entry((ptr)->next, type, member)
//


// my node
struct my_node {
    int num;
    struct list_head list;
};
//


// Solve
void bfs(int G[100][100], const int N, int d[100]) {
    struct list_head head;
    INIT_LIST_HEAD(&head);

    struct my_node *data = malloc(sizeof(struct my_node));
    data->num = 0;
    list_add_tail(&data->list, &head);
    int u;
    while(!list_empty(&head)) {
        data = list_first_entry(&head, struct my_node, list);
        u = data->num;
        free(data);
        for(int i = 0; i < N; ++i) {
            if(!G[u][i] || d[i] != 1 << 28) continue;
            d[i] = d[u] + 1;
            data = malloc(sizeof(struct my_node));
            data->num = i;
            list_add_tail(&data->list, &head);
        }
    }
}

