  int i, u, v;
  int next;
  int empty;

  for(u = 1; u <= n;u++){
    color[u] = WHITE;
    d[u] = INF;
  }

  color[s] = GRAY;
  d[s] = 0;
  empty = 0;

  //最初はsをキューに入れる。
  Enqueue(s);
  empty++;

  //空じゃなかったら
  while(empty != 0 ){    
    u = Dequeue();
    empty--;

    //取り出したキューがエッジを持つなら、訪問する。
