	d[next] = d[u] + 1;
	Enqueue(next);
	empty++;
      }
    }

    //訪問した場所は黒くする。
    color[u] = BLACK;
  }

  //一度も訪問されなければWHITEのままなので、 -1 を入れる。
  for(i = 1;i <= n;i++){
    if(color[i] == WHITE)
      d[i] = null;
  }
}

