void bfs(struct node G[][G_SIZE+1], int size, int id)
{
	int u, v, i;
	enque(id);
	while((u = deque()) != -1){
		if(u == 1){
			G[u][u].d = 0;
		}
		for(i = 1; i <= size; i++){
			if((G[u][i].l == 1) && (G[i][i].d == -1)){
				v = i;
				G[v][v].d = G[u][u].d + 1;
				enque(v);
			}
		}
	}
	return;
}

