int find(int n)
{
  if(n==list[n]) return n;
  return list[n]=find(list[n]);
}

int unit_friend(int a,int b)
{
  if(find(a)==find(b))
    {
      return 1;
    }
  else return 0;
}

void unit(int a,int b)
{
  a=find(a);
  b=find(b);

  if(a==b) return;

  list[b]=a;
}

