void Init(Queue *q, int max){
	q->max = max;
	q->num = q->front = q->rear = 0;
	q->que = calloc(max, sizeof(int));
}

void Enque(Queue *q, int x){
	q->num++;
	q->que[q->rear++] = x;
	if (q->rear == q->max)
		q->rear = 0;
}

void Deque(Queue *q, int *x){
	q->num--;
	*x = q->que[q->front++];
	if (q->front == q->max)
		q->front = 0;
}

