class Bfs(private val nodeList: List<Node>) {
    init {
        bfs()
    }

    fun print() {
        println(
            nodeList.joinToString("\n") {
                "${it.id} ${it.dest}"
            }
        )
    }

    private fun bfs() {
        var dest = 0
        var sameTimeNodes = listOf(nodeList.first())
        while (sameTimeNodes.isNotEmpty()) {
            val nodes = arrayListOf<Node>()
            sameTimeNodes.forEach { node ->
                if (node.dest == -1 || node.dest > dest) {
                    node.dest = dest
                }
                nodes.addAll(nodeList.filter { !it.visited && node.edges.contains(it.id) })
            }
            sameTimeNodes.forEach {
                it.visited = true
            }
            sameTimeNodes = nodes
            dest++
        }
    }
}

