fun BFS(a: Array<IntArray>): IntArray {
    val d = IntArray(a.size) { -1 }
    val q = LinkedList<Int>()
    val v = IntArray(a.size)
    d[0] = 0
    v[0] = 1
    q.add(0)
    while (!q.isEmpty()) {
        val c = q.removeFirst()
        for (i in a.indices) {
            if (a[c][i] == 1 && v[i] == 0) {
                v[i] = 1
                q.addLast(i)
                d[i] = d[c] + 1
            }
        }
    }
    return d
}

