        queue.add(s);

        for (int i = 0; i < n; i++) {
            Distance[i] = INF;
        }

        Distance[s] = 0;

        int u;
        while (!queue.isEmpty()){
            u = queue.peek();
            queue.remove();

            for (int v = 0; v < n; v++) {
                if (Mat[u][v] == 0) continue;
                if (Distance[v] != INF) continue;
                queue.add(v);
                Distance[v] = Distance[u] + 1;
