		}
	}

	public static void bfs() {
		NumDis current = queue.poll();
		int i = current.num;
		int d = current.dis;

		if (visited[i]) {
			return;
		}

		// to queue
		for(int j = 0; j < matrix[i].length; j++) {
			if (matrix[i][j] == 1) {
				queue.offer(new NumDis(j, d + 1));		
			}
		}

		// record
		distance[i] = d;
		visited[i] = true;
	}


