    	while(! Q.isEmpty()) {
    		int cur = Q.remove();//先頭要素を取り出す
    		for(int i=2; i<=n;i++) {//各行先に対して
    			if(D[i]==0 && v[cur][i]>0) {//未訪問で、curから辺があるなら
    				D[i] = D[cur]+1;
