			for(int j =0; j <  gyouretsu[now].length; j++){
				if(gyouretsu[now][j] == 1 && ans[j] == -1){
					array.add(j);
				}
			}
		}
		if(array.size() != 0){
		rec(gyouretsu, t+1, ans);
		}
	}

