public class Main {
    static int INF = (1 << 30) - 1;
    // static long L_INF = (1L << 62) - 1;
    // static long MOD = (long) 1e9 + 7;

    static class Edge {
        int v;
        int dist;

        Edge(int v, int dist) {
            this.v = v;
            this.dist = dist;
        }
    }

    static class Solver {
        int n;
        ArrayList<ArrayList<Integer>> g;

        // write your code
        void solve(InputReader in, PrintWriter out) {
            n = in.nextInt();
            g = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                ArrayList<Integer> al = new ArrayList<>();
                int u = in.nextInt() - 1;
                int k = in.nextInt();
                for (int j = 0; j < k; j++) {
                    al.add(in.nextInt() - 1);
                }
                g.add(al);
            }

            int[] ans = new int[n];
            Arrays.fill(ans, INF);
            ArrayDeque<Edge> que = new ArrayDeque<>();
            que.add(new Edge(0, 0));
            while (!que.isEmpty()) {
                Edge e = que.poll();
                if (ans[e.v] <= e.dist) {
                    continue;
                }
                ans[e.v] = e.dist;
                for (int i = 0; i < g.get(e.v).size(); i++) {
                    Integer next = g.get(e.v).get(i);
                    que.add(new Edge(next, e.dist + 1));
                }
            }
            for (int i = 0; i < n; i++) {
                if (ans[i] == INF) {
                    ans[i] = -1;
                }
                out.printf("%d %d\n", i + 1, ans[i]);
            }
        }

        void debug(Object... os) {
            System.err.println(Arrays.deepToString(os));
        }
    }

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Solver solver = new Solver();
        solver.solve(in, out);
        out.close();
    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.PriorityQueue;
import java.util.Scanner;

class adj_list implements Comparable<adj_list>{
    public int u,k,d;
    public int[] v;
    public boolean find_flg = false;
    public int compareTo (adj_list a){return this.u - a.u;}
}

public class Main {

    private static ArrayList<adj_list>  ar = new ArrayList<adj_list>();

    private static final int U          =  0,
                             K          =  1,
                             UNREARCHED = -1,
                             START      =  1,
                             S          =  0;

    public static void main(String[] args) {

        //input
         Scanner sc = new Scanner(System.in).useDelimiter(System.getProperty("line.separator"));
         int      N = sc.nextInt();

         adj_list a;String[] s;
         for(int i = 0;i < N;i++){
             s = sc.next().split("\\s");
             a = new adj_list();
             a.u = Integer.parseInt(s[U]);
             a.k = Integer.parseInt(s[K]);
             a.v = new int[a.k];
             for(int j=0;j<a.k;j++){a.v[j] = Integer.parseInt(s[j+2]);}
             a.d = UNREARCHED;
             ar.add(a);
         }
         Collections.sort(ar);

         //calculation
       	 BFS();

         //output
         for (adj_list d:ar) {System.out.println(d.u + " " + d.d);}
    }

    private static void BFS(){
    	PriorityQueue<adj_list> q = new PriorityQueue<adj_list>();
    	adj_list s = get_list(START);
    	s.d = S;
    	s.find_flg = true;
    	q.add(s);

    	while(!q.isEmpty()){
    		adj_list u = q.poll();
    		for(int v:u.v){
    			adj_list a = get_list(v);
    			if(a.find_flg){continue;}
    			a.d = u.d+1;
    			a.find_flg = true;
    			q.add(a);
    		}
    	}
    }

    private static adj_list get_list(int id){
        adj_list ret = null;
        for(adj_list a:ar){if(a.u == id){ret = a;}}
        return ret;
    }
}

