        int u, k, v;

        n = sc.nextInt();
        for (int i = 0; i < n; i++) {
            u = sc.nextInt();
            k = sc.nextInt();
            for (int j = 0; j < k; j++) {
                v = sc.nextInt();
                mat[u - 1][v - 1] = 1;
            }
        }
    }

    static void init() {
        for (int i = 0; i < n; i++) {
            d[i] = INFTY;
        }
        d[0] = 0;
    }

