        q.add(0);
        while (!q.isEmpty()) {
            int e = q.element(); q.remove();
            for (int i = 0; i < n; i++) {
                if (mat[e][i] == 1) {
                    if (d[i] == INFTY) {
                        d[i] = d[e] + 1;
                        q.add(i);
                    }
                }
            }
        }
    }

    static void out() {
