		for(int i=0; i<q1.size(); i++) {
			while(q1.size()>0) {
				int p=q1.peek();
				q1.remove();
				if(visited[p]==true) {continue;}
				else {
					visited[p]=true;
					ans[p]=i;
				}

				for(int j=0; j<n; j++) {
					if(connected[p][j]==true) {
						q2.add(j);
					}
				}
			}
			q1=q2;
			q2=new LinkedList<Integer>();
		}

	}
}

