public class Main {

	static final int WHITE = 0;
	static final int GRAY = 1;
	static final int BLACK = 2;

	static int n;
	static int[][] v;
	static int[] color;
	static Queue<Integer> queue;
	static int[] d;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
