			System.out.print(" ");
			System.out.println(d[i]);
		}
	}

	private static void bfs() {
		queue = new ArrayDeque<>();
		queue.offer(0);
		d[0] = 0;
		color[0] = GRAY;
		while (queue.peek() != null) {
			int visit = queue.poll();
			color[visit] = GRAY;
			for (int i = 0; i < n; i++) {
				if (v[visit][i] == 1 && color[i] == WHITE) {
					queue.offer(i);
					d[i] = d[visit] + 1;
					color[i] = GRAY;
				}
			}
			color[visit] = BLACK;
		}
	}

