					if(!visited.contains(temp2+1)) {
						visited.add(temp2+1);
						q.add(temp2+1);
					}
				}
			}
			path +=1;
		}
		for(int n = 1; n < totalVertex; n++) {
			if(result[n][1] == 0) {
				result[n][1] = -1;
			}
		}
		return result;
	}
}

