class Main{
    private static int[] d;
    private static int[][] g;
    private static int t = 0;
    public static void main(String[] Args) throws IOException{
        final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        final int n = Integer.parseInt(br.readLine());
        d = new int[n+1];
        for(int i = 0; i<=n; i++)
            d[i] = -1;
        g = new int[n+1][n+1];
        for(int i = 0; i<n; i++){
            final StringTokenizer st = new StringTokenizer(br.readLine(), " ");
            final int u = Integer.parseInt(st.nextToken());
            final int k = Integer.parseInt(st.nextToken());
            g[u][0] = k;
            for(int j = 1; j<=k; j++){
                g[u][j] = Integer.parseInt(st.nextToken());
            }
        }
        bfs(1);
        final StringBuilder sb = new StringBuilder();
        for(int i = 1; i<=n; i++){
            sb.append(i).append(' ').append(d[i]).append('\n');
        }
        System.out.print(sb);
    }
    private static void bfs(int e){
        final Deque<state> q = new ArrayDeque<state>();
        q.add(new state(e, 0));
        while(!q.isEmpty()){
            final state s = q.remove();
            final int id = s.id;
            int t = s.d;
            if(d[id]!=-1) continue;
            d[id] = t++;
            for(int i = 1, n = g[s.id][0]; i<=n; i++)
                q.add(new state(g[id][i], t));
        }
    }
}
class state{
    final int id;
    final int d;
    state(int id, int d){
        this.id = id;
        this.d = d;
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.Scanner;

public class Main {
	void run() {
		Scanner sc = new Scanner(System.in);
		int V = sc.nextInt();//頂点数
		int[][] E = new int[V+1][V+1];//a→cに向かうかどうか 1なら向かう
		for(int i = 1; i <= V; i++) {
			int a = sc.nextInt();//頂点番号
			int b = sc.nextInt();//出次数
			for(int k = 0; k < b; k++) {
				int c = sc.nextInt();//出次している番号
				E[a][c] = 1; //a→cに向かうかどうか 1なら向かう
			}
		}
		int[] D = bfs(V, E);

		for(int i = 1; i <= V; i++) {
			System.out.println(i + " " + (D[i] -1));
		}
		sc.close();
	}

	int[] bfs(int V, int[][] E) { //V:頂点数, E[a][b]:a→bに向かうなら1、そうでないなら0
		Queue<Integer> Q = new ArrayDeque<>();
		Q.add(1);//ノード1から始める
		int D[] = new int[V+1];
		D[1] = 1; //D[a] : ノードaの深さ（D[a]=0ならまだ通過していない）
		while(Q.size() > 0) {//キューに値が入っている間
			int cur = Q.poll();	//cur : 今考えている点
			for(int d = 1; d <= V; d++) { //d : 次向かう点
				if(E[cur][d] == 1 & D[d] == 0) { //E[cur][d]cur→dに向かうかどうか 1なら次向かう
					D[d] = D[cur]+1; //Dに深さを格納
					Q.add(d);//キューに値追加
				}
			}
		}
		return D; //各ノードの深さを返す
	}

	void debug(Object... o) {
		System.out.println(Arrays.deepToString(o));
	}

	public static void main(String[] args) {
		new Main().run();
	}
}

