public class Main{

	public static void main(String[] args) {
		Scanner s = new Scanner(System.in);
		int cnt = Integer.parseInt(s.nextLine());
		int[][] input = new int[cnt][cnt+2];
		for(int i=0 ; i<cnt ; i++) {
			String[] tmp = s.nextLine().split(" ");
			int[] a = new int[tmp.length];
			for(int j=0 ; j<a.length ; j++) {
				a[j] = Integer.parseInt(tmp[j]);
			}
			input[i] = a;
		}
		int[] result = bfs(input);
		for(int i=0 ; i<result.length ; i++) {
			System.out.println((i+1) + " " + result[i]);
		}
	}

	public static int[] bfs(int[][] input) {
		int[] result = new int[input.length];
		boolean[] alreadyVisit = new boolean[input.length];
		for(int i=0 ; i<result.length ; i++) {
			result[i] = -1;
			alreadyVisit[i] = false;
		}
		LinkedList<Integer> graph = new LinkedList<Integer>();
		LinkedList<Integer> shortPath = new LinkedList<Integer>();
		graph.offer(new Integer(1));
		shortPath.offer(new Integer(0));

		while(! graph.isEmpty()) {
			Integer g = (Integer) graph.poll();
			Integer s = (Integer) shortPath.poll();
			if(alreadyVisit[g.intValue()-1]){}
			else {
				alreadyVisit[g.intValue()-1] = true;
				if(result[g.intValue()-1]==-1)
					result[g.intValue()-1] = s.intValue();
				for(int i=0 ; i<input[g.intValue()-1][1] ; i++) {
					graph.offer(new Integer(input[g.intValue()-1][i+2]));
					shortPath.offer(new Integer(s.intValue()+1));
				}
			}
		}
		return result;
	}
}

import java.util.LinkedList;
import java.util.Scanner;
import java.util.Iterator;

class Graph {
	private int totalVertex;
	private LinkedList<LinkedList<Integer>> adjList;
	//adjacency list of edges
	public Graph() { totalVertex = 0; }
	public int getTotalVertex() { return totalVertex; }
	public void loadAdjList() {
		Scanner in = new Scanner(System.in);
		totalVertex = in.nextInt();
		adjList = new LinkedList<LinkedList<Integer>>();
		for(int i = 0; i < totalVertex; i ++) {
			LinkedList<Integer> tmp = new LinkedList<Integer>();
			int idx1 = in.nextInt() - 1; //-1, index
			int degree = in.nextInt();
			//System.out.println("mark idx1 = " + idx1 + " degree = " + degree);
			for(int j = 0; j < degree; j ++) {
				int idx2 = in.nextInt() - 1; //-1, index
				tmp.add(idx2);
			}	
			adjList.add(tmp);
		}
		in.close();
	}

	public int[] computeDistDFS(int s) {
		LinkedList<Integer> q = new LinkedList<Integer>();
		q.add(s);
		int[] visited = new int[totalVertex];
		int[] dist = new int[totalVertex];
		int v, u;
		for(v = 0; v < totalVertex; v ++) {
			visited[v] = 0; 
			dist[v] = -1; 
		}
		dist[s] = 0;
		visited[s] = 1;
		while(!q.isEmpty()) {
			u = q.remove(0); //remove the first item from the list/queue
			Iterator<Integer> it = adjList.get(u).iterator();
			while(it.hasNext()) {
				v = it.next();
				if(visited[v] == 0) {
					q.add(v); //add to the end of the list/queue
					dist[v] = dist[u] + 1;
					visited[v] = 1;
				}
			}
		}
		return dist;
	}
}

public class Main {
	public static void main(String[] args) {
		Graph g = new Graph();
		g.loadAdjList();
		int[] dist = g.computeDistDFS(0);
		for(int i = 0; i < g.getTotalVertex(); i ++) {
			System.out.println((i+1) + " " + dist[i]);
		}
	}
}

