		while(!q.isEmpty()) {
			int u=q.remove();
			for(int i=1;i<=list[u][0];i++) {
				int next=list[u][i];
				if(S[next]==-1) {
					S[next]=S[u]+1;
					q.add(next);
				}
			}
		}

		PrintWriter out=new PrintWriter(System.out);
		for(int i=1;i<=n;i++) {
			out.println(i+" "+S[i]);
		}
