    AOJ(FastScanner sc) {
        N = sc.nextInt();
        d = IntStream.range(0, N).map(i -> -1).toArray();
        color = IntStream.range(0, N).mapToObj(i -> "WHITE").toArray();
        M = new boolean[N][N];
        for (int i = 0; i < N; i++) {
            int u = sc.nextInt() - 1;
            final int K = sc.nextInt();
            for (int j = 0; j < K; j++) {
                int v = sc.nextInt() - 1;
                M[u][v] = true;
            }
        }
    }

    void solve(PrintWriter out) {
        Deque<Integer> Q = new ArrayDeque<>();
        color[0] = "GRAY";
        d[0] = 0;
        Q.addLast(0);
        while (!Q.isEmpty()) {
            int i = Q.removeFirst();
            for (int j = 0; j < N; j++) {
                if (M[i][j] && color[j].equals("WHITE")) {
                    color[j] = "GRAY";
                    d[j] = d[i] + 1;
                    Q.addLast(j);
                }
            }
            color[i] = "BLACK";
        }

        for (int i = 0; i < N; i++) {
            out.println((i+1) + " " + d[i]);
        }
    }

}

// https://qiita.com/p_shiki37/items/a0f6aac33bf60f5f65e4
class FastScanner {

    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        } else {
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() {
        if (hasNextByte()) {
            return buffer[ptr++];
        } else {
            return -1;
        }
    }

    private static boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
            ptr++;
        }
        return hasNextByte();
    }

    public String next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public long nextLong() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }

    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
            throw new NumberFormatException();
        }
        return (int) nl;
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

