	public Graph1(int n) {
		vertexs = new ArrayList<Vertex>();
		indexes = new int[n + 1];
		queue = new LinkedList<Vertex>();
	}

	public void add(String info) {
		int id;
		int[] edge;
		String[] _edge;

		StringTokenizer st = new StringTokenizer(info);
		id = Integer.parseInt(st.nextToken());
		_edge = new String[Integer.parseInt(st.nextToken())];
		edge = new int[_edge.length];
		for (int i = 0; i < _edge.length; i++) {
			_edge[i] = st.nextToken();
		}
		// Arrays.sort(_edge);
		for (int i = 0; i < edge.length; i++) {
			edge[i] = Integer.parseInt(_edge[i]);
		}
		vertexs.add(new Vertex(id, edge));
		indexes[id] = vertexs.size() - 1;
	}

	public Vertex get(int id) {
		return vertexs.get(indexes[id]);
	}

	public void dfs(int t) {
		for (Vertex v : vertexs) {
			t = v.dfs(t);
		}
	}

	public void bfs(int s) {
		Vertex v1, v2;

		get(s).d = 0;
		queue.add(get(s));
		while (!queue.isEmpty()) {
			v1 = queue.removeFirst();
			for (int i = 0; i < v1.edge.length; i++) {
				v2 = get(v1.edge[i]);
				if (v2.d == -1) {
					v2.d = v1.d + 1;
					queue.add(v2);
				}
			}
		}
	}

	class Vertex {
		private int id, d, f;
		private int[] edge;

		private Vertex(int id, int[] edge) {
			this.id = id;
			d = -1;
			f = 0;
			this.edge = edge;
		}

		private int dfs(int t) {
			if (d == -1) {
				d = ++t;
				for (int i = 0; i < edge.length; i++) {
					t = get(edge[i]).dfs(t);
				}
				f = ++t;
			}
			return t;
		}

		public String printTime() {
			return String.format("%d %d %d\n", id, d, f);
		}

		public String printDistance() {
			return String.format("%d %d\n", id, d);
		}
	}
}

import java.util.LinkedList;
import java.util.Scanner;
import java.util.Arrays;
import java.util.Iterator;

class Graph {
	private int totalVertex;
	private LinkedList<LinkedList<Integer>> adjList;
	private int[] bfs;
	//adjacency list of edges
	public Graph() { totalVertex = 0; }
	public void loadAdjList() {
		Scanner in = new Scanner(System.in);
		totalVertex = in.nextInt();
		adjList = new LinkedList<LinkedList<Integer>>();
		for(int i = 0; i < totalVertex; i ++) {
			LinkedList<Integer> tmp = new LinkedList<Integer>();
			int idx1 = in.nextInt() - 1;
			int degree = in.nextInt();
			//System.out.println("mark idx1 = " + idx1 + " degree = " + degree);
			for(int j = 0; j < degree; j ++) {
				int idx2 = in.nextInt() - 1;
				tmp.add(idx2);
			}	
			adjList.add(tmp);
		}
		in.close();
		bfs = new int[totalVertex];
	}
	public void BFS(int s) 
    { 
        // Mark all the vertices as not visited(By default 
        // set as false) 
        boolean visited[] = new boolean[totalVertex]; 

        // Create a queue for BFS 
        LinkedList<Integer> queue = new LinkedList<Integer>(); 
        LinkedList<Integer> queue2 = new LinkedList<Integer>(); 

        // Mark the current node as visited and enqueue it 
        visited[s]=true; 
        queue.add(s);

        while (queue.size() != 0) 
        { 
            // Dequeue a vertex from queue and print it 
            s = queue.poll();
            queue2.add(s);

            // Get all adjacent vertices of the dequeued vertex s 
            // If a adjacent has not been visited, then mark it 
            // visited and enqueue it 
            Iterator<Integer> i = adjList.get(s).listIterator(); 
            while (i.hasNext()) 
            { 
                int n = i.next(); 
                if (!visited[n]) 
                {
                    visited[n] = true; 
                    queue.add(n);
                    bfs[n] = bfs[s] + 1;
                }

            } 
        } 
        for(int i = 0; i < totalVertex; i++) {
        	if(i != 0 && bfs[i] == 0) bfs[i] = -1;
        }
        for(int i = 0; i < totalVertex; i++) {
        	System.out.print((i + 1) + " " + bfs[i]);
        	System.out.println();
        }
    }
}

public class Main {
	public static void main(String argv[]) {
		Graph g = new Graph();
		g.loadAdjList();
		g.BFS(0);
	}
}

