		/**
		 * @param matrix グラフ
		 * @param v[] 訪問済リスト
		 *
		 * */
		public static int[] bfs(int[][] matrix, int[] v, int from) {

			for (int to = 1; to < v.length; to++) {
				if (matrix[from][to] == 1) {
					int count = v[from] + 1;
					if (v[to] == 0 || count < v[to]) {
						v[to] = count;
					}
				}
			}
			return v;
		}
	}

