    for(int i =0; i<n; i++){
      u = sc.nextInt();
      k = sc.nextInt();
      for(int j = 0; j<k; j++){
        v = sc.nextInt();
        M[u-1][v-1] = 1;
      }
    }
    bfs(0);
  }

  static void bfs(int s){
    queue.add(s);
    for(int i = 0; i<n; i++){
      d[i] = -1;
    }
    d[s] = 0;
    int u;
    while(queue.peek() != null){
      u = queue.peek();
      queue.remove();
      for(int v = 0; v<n; v++){
        if(M[u][v] == 0)continue;
        if( d[v] != -1)continue;
        d[v] = d[u]+1;
        queue.add(v);
      }
    }

    for(int i = 0; i<n; i++){
      bl.append(i+1).append(" ").append(d[i]).append("\n");
    }
    System.out.print(bl);
  }

}

