public class Main {
    private int N;
    private int[][] G;

    private int[] distance;

    public Main(Scanner sc) {
        N = sc.nextInt();
        G = new int[N][];
        for (int i = 0; i < N; i++) {
            G[i] = new int[N];
        }
        for (int i = 0; i < N; i++) {
            int u = sc.nextInt() - 1;
            int adjNum = sc.nextInt();
            for (int j = 0; j < adjNum; j++) {
                int v = sc.nextInt() - 1;
                G[u][v] = 1;
            }
        }

        distance = new int[N];
        Arrays.fill(distance, -1);
    }

    public void bfs(int node) {
        Queue<Integer> que = new LinkedList<>();
        que.offer(node);
        distance[node] = 0;

        while (!que.isEmpty()) {
            int currNode = que.poll();
            for (int i = 0; i < N; i++) {
                if (distance[i] < 0 && G[currNode][i] == 1) {
                    que.offer(i);
                    distance[i] = distance[currNode] + 1;
                }
            }
        }
    }

    public void print() {
        for (int i = 0; i < N; i++) {
            System.out.println(i+1 + " " + distance[i]);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Main m = new Main(sc);
        m.bfs(0);
        m.print();
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.PriorityQueue;
import java.util.Scanner;

class adj_list implements Comparable<adj_list>{
    public int u,k,d;
    public int[] v;
    public boolean find_flg = false;
    public int compareTo (adj_list a){return this.u - a.u;}
}

public class Main {

    private static ArrayList<adj_list>  ar = new ArrayList<adj_list>();

    private static final int U          =  0,
                             K          =  1,
                             UNREARCHED = -1,
                             START      =  1,
                             S          =  0;

    public static void main(String[] args) {

        //input
         Scanner sc = new Scanner(System.in).useDelimiter(System.getProperty("line.separator"));
         int      N = sc.nextInt();

         adj_list a;String[] s;
         for(int i = 0;i < N;i++){
             s = sc.next().split("\\s");
             a = new adj_list();
             a.u = Integer.parseInt(s[U]);
             a.k = Integer.parseInt(s[K]);
             a.v = new int[a.k];
             for(int j=0;j<a.k;j++){a.v[j] = Integer.parseInt(s[j+2]);}
             a.d = UNREARCHED;
             ar.add(a);
         }
         Collections.sort(ar);

         //calculation
       	 BFS();

         //output
         for (adj_list d:ar) {System.out.println(d.u + " " + d.d);}
    }

    private static void BFS(){
    	PriorityQueue<adj_list> q = new PriorityQueue<adj_list>();
    	adj_list s = get_list(START);
    	s.d = S;
    	q.add(s);

    	while(!q.isEmpty()){
    		adj_list u = q.poll();
    		for(int v:u.v){
    			adj_list a = get_list(v);
    			if(a.find_flg){continue;}
    			a.d = u.d+1;
    			a.find_flg = true;
    			q.add(a);
    		}
    	}
    }

    private static adj_list get_list(int id){
        adj_list ret = null;
        for(adj_list a:ar){if(a.u == id){ret = a;}}
        return ret;
    }
}

