    public static void Main()
    {
        var n = int.Parse(Console.ReadLine().Trim());
        var map = new List<int>[n];
        var d = new int[n];
        for (int i = 0; i < n; i++)
        {
            d[i] = -1;
            map[i] = new List<int>();
            string[] line = Console.ReadLine().Trim().Split(' ');
            var a = int.Parse(line[0]) - 1;
            var b = int.Parse(line[1]);
            for (int j = 0; j < b; j++)
            {
                var c = int.Parse(line[j + 2]) - 1;
                map[i].Add(c);
            }
        }
        d[0] = 0;
        goDfs(map, d);
        print(d);
    }
    public static void print(int[] d)
    {
        var dL = d.Length;
        for (int i = 0; i < dL; i++)
            Console.WriteLine("{0} {1}", i + 1, d[i]);
    }
    public static void goDfs(List<int>[] map, int[] d)
    {
        var n = map.Length;
        var used = new bool[n];
        used[0] = true;
        var q = new Queue<P>();
        foreach (var x in map[0])
        {
            q.Enqueue(new P { to = x, step = 1 });
            used[x] = true;
        }
        while (q.Count() > 0)
        {
            var w = q.Dequeue();
            d[w.to] = w.step;
            foreach (var x in map[w.to])
                if (!used[x])
                {
                    q.Enqueue(new P { to = x, step = w.step + 1 });
                    used[x] = true;
                }
        }
    }
}

