class Graph
{
    private int n;
    private List<int>[] adj;
    public int[] d;
    public Graph(int n)
    {
        this.n = n;
        adj = new List<int>[n];
        d = new int[n];
        for (int i = 0; i < n; i++)
        {
            adj[i] = new List<int>();
            d[i] = -1;
        }
    }
    public void SetEdge(int s, int g)
    {
        if (s > n || g > n)
            return;
        adj[s - 1].Add(g);
    }
    public List<int> GetEdge(int i)
    {
        return adj[i - 1];
    }
    public void BFS(int s)
    {
        d[s - 1] = 0;
        Queue<int> q = new Queue<int>();
        q.Enqueue(s);
        while (q.Count != 0)
        {
            int u = q.Dequeue();
            foreach (var v in GetEdge(u))
            {
                if (d[v - 1] == -1)
                {
                    d[v - 1] = d[u - 1] + 1;
                    q.Enqueue(v);
                }
            }
        }
    }
}

