    class Breadth_First_Search
    {

        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            var G = new bool[n][];

            for (int i = 0; i < n; i++)
            {
                var token = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
                var row = token[0] - 1;
                G[row] = new bool[n];
                for (int j = 0; j < token[1]; j++)
                    G[row][token[2 + j] - 1] = true;
            }

            for (int i = 0; i < n; i++)
            {
                Console.WriteLine("{0} {1}", i + 1, BreadthFirstSearch(G, i));
            }
        }

        static int BreadthFirstSearch(bool[][] graph, int destination)
        {
            var n = graph.Length;
            var done = new bool[n];
            var dist = new int[n];
            var queue = new Queue<int>();

            done[0] = true;
            dist[0] = 0;
            queue.Enqueue(0);

            while (queue.Count > 0)
            {
                var r = queue.Dequeue();
                if (r == destination) return dist[r];
                for (int i = 0; i < n; i++)
                {
                    if (graph[r][i] && !done[i])
                    {
                        done[i] = true;
                        dist[i] = dist[r] + 1;
                        queue.Enqueue(i);
                    }
                }
            }

            return -1;

        }
    }
}

