		int[,] G = new int[n,n];

		for(int i = 0; i < n; i++) {
			int[] u = Array.ConvertAll(Console.ReadLine().Split(" ".ToCharArray()), int.Parse);

			for(int j = 0; j < u[1];  j++) {
				G[u[0]-1, u[j+2]-1] = 1;
			}
		}

		Node[] nodes = new Node[n];
		for(int i = 0; i < n; i++) {
			nodes[i] = new Node(i);
		}

		for(int i = 0; i < n; i++) {
			for(int j = 0; j < n; j++) {
				if(G[i,j] != 0) { 
					nodes[i].Children.Add(nodes[j]);
				}
			}
		}

		for(int i = 0; i < n; i++) {
			for(int j = 0; j < n; j++) nodes[j].Added = false;
			BFS(nodes[0], nodes[i], nodes[0].Children.ToArray());
		}

		for(int i = 0; i < n; i++) {
			Console.WriteLine(nodes[i]);
		}
	}

	static void BFS(Node start, Node goal,Node[] onWays)
	{
		if(start == goal) return;
		else {
			goal.d++;

			List<Node> nexts = new List<Node>();
			foreach (var o in onWays) {
				if(o == goal) return;

				if(!o.Added) {
					foreach(Node p in o.Children.ToArray()){
						if(p != start) nexts.Add(p);
					}
					o.Added = true;
				}
			}
			if(nexts.Count != 0) BFS(start, goal, nexts.ToArray());
			else goal.d = -1;
		}
	}

}

