namespace CompProgLib
{
    public class Graph
    {
        public class Node
        {
            public List<int> Vertex { get; internal set; }
            public int D { get; internal set; }
            public int F { get; internal set; }
            public bool IsVisited { get; internal set; }
            public int Depth { get; internal set; }

            public Node(List<int> v)
            {
                Vertex = v;
                Depth = -1;
            }
        }

        public Dictionary<int, Node> Adj { get; set; }

        public Graph()
        {
            Adj = new Dictionary<int, Node>();
        }

        /// <summary>
        /// 隣接行列の指定したインデックスに値をセットする
        /// </summary>
        /// <param name="index">頂点u</param>
        /// <param name="item">頂点uに接続する頂点</param>
        public void SetGraph(int index, int[] item)
        {
            Adj.Add(index, new Node(item.ToList()));
        }

        /// <summary>
        /// 行列を0で初期化する
        /// </summary>
        public void Clear() { Adj.Clear(); }

        /// <summary>
        /// 深さ優先探索
        /// </summary>
        private int Time = 0;
        public void DFS(int v)
        {
            Adj[v].D = ++Time;
            Adj[v].IsVisited = true;
            foreach (int vertex in Adj[v].Vertex)
            {
                if (!Adj[vertex].IsVisited) DFS(vertex);
            }
            Adj[v].F = ++Time;
        }

        /// <summary>
        /// 幅優先探索
        /// </summary>
        /// <param name="v"></param>
        public void BFS(int v)
        {

            Queue<Node> que = new Queue<Node>();

            Adj[v].Depth = 0;
            Adj[v].IsVisited = true;
            que.Enqueue(Adj[v]);

            while (que.Count() != 0)
            {
                Node node = que.Dequeue();
                foreach (int vertex in node.Vertex)
                {
                    if (!Adj[vertex].IsVisited)
                    {
                        Adj[vertex].IsVisited = true;
                        Adj[vertex].Depth = node.Depth + 1;
                        que.Enqueue(Adj[vertex]);

                    }
                }
            }

        }
    }
}

