        public List<int> adjacentIds;
    }

    static void Main(string[] args)
    {
    	// 行数を取得
        int n = int.Parse(Console.ReadLine().Split()[0]);

        // nodeを作成
        for (int i = 0; i < n; i++)
        {
            nodes.Add(new Node());
        }

