    static void Bfs(Node start)
    {
        start.dist = 0;
        queue.Enqueue(start);
        while (queue.Count > 0)
        {
            Node node = queue.Dequeue();
            foreach (var id in node.adjacentIds)
            {
                if (nodes[id].dist == -1)
                {
                    nodes[id].dist = node.dist + 1;
                    queue.Enqueue(node);
                }
            }
        }
    }
