            Program.shortestPath = new int[n];
            Program.shortestPath[0] = 0;
            Program.isVisited = new bool[Program.n];
            Program.isVisited[0] = true;
            for (int i = 1; i < Program.n; i++)
            {
                Program.shortestPath[i] = -1;
            }
            for (int i = 0; i < Program.n; i++)
            {
                int[] tmpLine = Console.ReadLine()
                                       .Split(' ')
                                       .Select(s => int.Parse(s))
                                       .ToArray();
                for (int j = 2; j <= tmpLine[1] + 1; j++)
                {
                    Program.neighborList[tmpLine[0] - 1, tmpLine[j] - 1] = 1;
                }
            }
            Queue<int> nodeQueue = new Queue<int>();
            nodeQueue.Enqueue(1);
            while (nodeQueue.Count() > 0)
            {
                Program.BreadthFirstSearch(nodeQueue);
            }
            for (int i = 0; i < Program.n; i++)
            {
                Console.WriteLine(string.Format("{0} {1}", i + 1, Program.shortestPath[i]));
            }
        }

        static void BreadthFirstSearch(Queue<int> nodeQueue)
        {
            int tmpNode = nodeQueue.Dequeue();

            for (int i = 0; i < Program.n; i++)
            {
                if (!Program.isVisited[i] && Program.neighborList[tmpNode - 1, i] == 1)
                {
                    Program.shortestPath[i] = Program.shortestPath[tmpNode - 1] + 1;
                    Program.isVisited[i] = true;
                    nodeQueue.Enqueue(i + 1);
                }
            }

        }
    }
}

