  public Node(int id,int depth){
    this.id = id;
    this.adjacency = new int[depth];
  }

  public void RegistAdjacency(int child){
    this.adjacency[point] = child;
    point++;
  }
}

class NodeQueue{
  Node[] Nodes = new Node[100];
  int head = 0;
  int tail = 0;

  public void enque(Node N){
    Nodes[tail] = N;
    tail++;
  }

  public Node deque(){
    Node res = Nodes[head];
    head++;
    return res;
  }

  public bool IsNotEmpty(){
    if(tail != head){
      return true;
    }else{
      return false;
    }
  }
}

