        {
            this.No = no;
            Dist = int.MaxValue;
            Edges = new List<Edge>();
        }
    }

    internal class Edge
    {
        public int From;
        public int To;
        public int Cost;


        public Edge(int fr, int to, int cost = 0)
        {
            From = fr;
            To = to;
            Cost = cost;
        }

    }

    internal class Graph
    {
        public List<Node> Nodes;

        public Node this[int i]
        {
            set { Nodes[i] = value; }
            get { return Nodes[i]; }
        }

        public Graph(int N)
        {
            Nodes = new List<Node>();
            for (int i = 0; i < N; i++)
            {
                Nodes.Add(new Node(i));
            }
        }

    }

    internal class Solution
    {
        public int N;
        public Graph G;

        public void Run()
        {
            N = Input.ReadInt();
            G = new Graph(N);

            for (int i = 0; i < N; i++)
            {
                var line = Input.ReadIntArray();
                var o = line[1];
                for (int j = 0; j < o; j++)
                {
                    int fr = i;
                    int to = line[2 + j] - 1;
                    G[i].Edges.Add(new Edge(fr, to));
                }
            }

            RunGraph();
            for (int i = 0; i < N; i++)
            {
                Console.WriteLine("{0} {1}", i+1, G[i].Dist);
            }
        }

        public void RunGraph()
        {
            var q = new Queue<Data>();
            q.Enqueue(new Data(0, new Edge(-1, 0)));

            while (q.Count > 0)
            {
                var d = q.Dequeue();
                var e = d.Edge;
                var to = e.To;
                if(G[to].Dist < int.MaxValue) continue;
                G[to].Dist = d.Dist;
                foreach(var _e in G[to].Edges)
                    q.Enqueue(new Data(G[to].Dist + 1, _e));
            }
        }

    }


