namespace CSharp_AtCoder
{

    class Program
    {
        static int N;
        static List<int>[] edges;
        static int[] d;
        static bool[] find;

        static void BFS()
        {
            Queue<int> que = new Queue<int>();
            que.Enqueue(0);
            find[0] = true;

            while(que.Count != 0)
            {
                int from = que.Dequeue();
                //Console.WriteLine($"from:{from}");
                foreach(var to in edges[from])
                {
                    if (!find[to])
                    {
                        que.Enqueue(to);
                        find[to] = true;
                    }

                    // from -> to の更新処理
                    // -1 or d[from] + 1 < d[to] で更新
                    if(d[to] == -1 || d[from] + 1 < d[to])
                    {
                        d[to] = d[from] + 1;
                    }                   
                }
            }

        }

        static void Main(string[] args)
        {
            // 入力
            N = int.Parse(Console.ReadLine());

            // 初期化
            edges = new List<int>[N];
            d = new int[N];
            find = new bool[N];
            for (int i = 0; i < N; i++)
            {
                edges[i] = new List<int>();
                d[i] = -1;
            }
            d[0] = 0;        

            // 隣接リスト生成
            // u k v(1) ... v(k)
            for(int i = 0; i < N; i++)
            {
                int[] input = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
                int from = input[0] - 1;
                int k = input[1];
                for(int j = 0; j < k; j++)
                {
                    edges[from].Add(input[j + 2] - 1);
                }
            }

            BFS();

            // 出力
            for(int i = 0; i < N; i++)
            {
                Console.WriteLine($"{i + 1} {d[i]}");
            }

        }
    }
}

