		private bool[][] Path { set; get; }
		private int Size { set; get; }
		private const bool Exist = true;

		private enum State
		{
			NotVisited, Stay, Visited
		};

		public void GetPath ( int beginPoint, int adjacencyPoint )
		{
			Path[beginPoint - 1][adjacencyPoint - 1] = Exist;
		}

		public int[] BreadthFirstSeach ( int beginSearchPoint )
		{
			beginSearchPoint -= 1;

			//initialize
			Queue<int> searchQueue = new Queue<int> (Size);

			State[] visitState = Enumerable.Repeat (State.NotVisited, Size).ToArray ();

			const int CannotVisit = -1;
			int[] distance = Enumerable.Repeat (CannotVisit, Size).ToArray ();

			//process
			searchQueue.Enqueue (beginSearchPoint);
			distance[beginSearchPoint] = 0;

			while (searchQueue.Count != 0)
			{
				int item = searchQueue.Dequeue ();

				visitState[item] = State.Visited;

				for (int lp = 0; lp < Size; lp++)
				{
					//??£??\????????????
					if (Path[item][lp] == Exist)
					{
						//????¨??????????
						if (visitState[lp] == State.NotVisited)
						{
							//????´¢????±??????\??????
							searchQueue.Enqueue (lp);
							visitState[lp] = State.Stay;
							distance[lp] = distance[item] + 1;
						}
					}
				}
			}

			return distance;
		}
	}
