    class Program
    {
        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());

            var nodes = new Dictionary<int, int[]>();
            var costs = new int[n];

            for (var i = 0; i < n; i++)
            {
                var line = Console.ReadLine().Split(' ').Select(value => int.Parse(value) - 1).ToArray();
                nodes.Add(line[0], line.Skip(2).ToArray());

                costs[i] = int.MaxValue;
            }
            costs[0] = 0;

            var queue = new Queue<int>();
            queue.Enqueue(0);

            var isArrived = new bool[n];

            while (queue.Count > 0)
            {
                Bfs(queue, nodes, costs, isArrived);
            }

            for (var i = 0; i < n; i++)
            {
                Console.WriteLine($"{i + 1} {(costs[i] == int.MaxValue ? -1 : costs[i])}");
            }
        }

        private static void Bfs(Queue<int> queue, Dictionary<int, int[]> nodes, int[] costs, bool[] isArrived)
        {
            var id = queue.Dequeue();
            isArrived[id] = true;

            foreach(var nextId in nodes[id])
            {
                if (!isArrived[nextId])
                {
                    queue.Enqueue(nextId);
                    costs[nextId] = Math.Min(costs[nextId], costs[id] + 1);
                }
            }
        }
    }
}

