        {
            int n = int.Parse(Console.ReadLine());
            Node[] nodes = new Node[n + 1];
            for (int i = 0; i < n; i++)
            {
                int[] temp = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
                nodes[temp[0]] = new Node();
                for (int k = 0; k < temp[1]; k++)
                {
                    nodes[temp[0]].adj.Add(temp[k + 2]);
                }
            }
            for (int i = 1; i <= n; i++)
                BFS(nodes, i);

            for (int i = 1; i <= n; i++)
                Console.WriteLine(i + " " + nodes[i].d);

        }

        static void BFS(Node[] nodes, int pos) {
            Queue<int[]> q = new Queue<int[]>();
            HashSet<int> visted = new HashSet<int>();
            q.Enqueue(new int[2]{ 1, 0});
            while (q.Count > 0) {
                int[] curr = q.Dequeue();
                visted.Add(curr[0]);
                if (curr[0] == pos)
                {
                    nodes[pos].d = curr[1];
                    return;
                }
                for (int i = 0; i < nodes[curr[0]].adj.Count; i++)
                    if(!visted.Contains(nodes[curr[0]].adj[i])) q.Enqueue(new int[2] { nodes[curr[0]].adj[i], curr[1] + 1 });
            }

            nodes[pos].d = -1;
        }

    }
