namespace Graph_I
{
    class Breadth_First_Search
    {

        static int[] dist;

        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            var G = new bool[n][];
            dist = new int[n];

            for (int i = 0; i < n; i++)
            {
                var token = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
                var row = token[0] - 1;
                G[row] = new bool[n];
                for (int j = 0; j < token[1]; j++)
                    G[row][token[2 + j] - 1] = true;
            }

            var str = new StringBuilder();

            for (int i = 0; i < n; i++)
                str.Append(i + 1).Append(" ").Append(BreadthFirstSearch(G, i)).Append("\n");
            Console.Write(str.ToString());
        }

        static int BreadthFirstSearch(bool[][] graph, int destination)
        {
            if (dist[destination] != 0) return dist[destination];
            var n = graph.Length;
            var done = new bool[n];
            var queue = new Queue<int>();

            done[0] = true;
            dist[0] = 0;
            queue.Enqueue(0);

            while (queue.Count > 0)
            {
                var r = queue.Dequeue();
                if (r == destination) return dist[r];
                for (int i = 0; i < n; i++)
                {
                    if (graph[r][i] && !done[i])
                    {
                        done[i] = true;
                        dist[i] = dist[r] + 1;
                        queue.Enqueue(i);
                    }
                }
            }

            return -1;

        }
    }
}

