        var q = new Queue<Data>();
        q.Enqueue(new Data(0, new Edge(-1, 0)));
        while (q.Count > 0)
        {
            Data d = q.Dequeue();
            Node nd = G[d.edge.to];
            if(nd.dist != U.INFTY) continue;
            nd.dist = d.dist;
            foreach (var ee in nd.edges)
            {
                q.Enqueue(new Data(nd.dist+1, ee));
            }
        }

        for (int i = 0; i < N; i++)
        {
            if (G[i].dist == U.INFTY) G[i].dist = -1;
            Console.WriteLine("{0} {1}", i+1, G[i].dist);
        }
    }
}

