struct G {

    public int edge, d;
    public int[] adj;

    public G(int n) {
        edge = n;
        adj = new int[n];
        d = -1;
    }
}

class Breadth_First_Search {
    public static void Main() {

        int n = int.Parse(Console.ReadLine());
        G[] g = new G[n + 1];

        for(int i = 0; i < n; i++) {
            string[] str = Console.ReadLine().Split(' ');
            int stringToInt1 = int.Parse(str[0]), stringToInt2 = int.Parse(str[1]);
            g[stringToInt1] = new G(stringToInt2);

            for(int j = 0; j < stringToInt2; j++) {
                g[stringToInt1].adj[j] = int.Parse(str[j + 2]);
            }
        }

        g[1].d = 0;
        var queue = new Queue<int>();
        queue.Enqueue(1);

        while(queue.Count > 0) {
            int id = queue.Dequeue();

            for(int i = 0; i < g[id].edge; i++) {
                if(g[g[id].adj[i]].d == -1) {
                    g[g[id].adj[i]].d = g[id].d + 1;
                    queue.Enqueue(g[id].adj[i]);
                }
            }
        }

        for(int i = 1; i <= n; i++) {
            Console.WriteLine(i + " " + g[i].d);
        }

    }
}

