class Program
{
    static int n;
    // Nodeのリスト
    static List<Node> nodes = new List<Node>();
    // 辿っているQueue
    static Queue<Node> queue = new Queue<Node>();

    // Node
    class Node
    {
        // 距離
        public int dist = -1;
        // 隣接NodeのId（index）
        public List<int> adjacentIds;
    }

    // メイン
    static void Main(string[] args)
    {
        Parse();

        Bfs(nodes[0]);

        Print();
    }

    // 入力をパース
    static void Parse()
    {
        // 行数を取得
        n = int.Parse(Console.ReadLine().Split()[0]);

        // nodeを作成
        for (int i = 0; i < n; i++)
        {
            nodes.Add(new Node());
        }

        // nodeの中身設定
        for (int i = 0; i < n; i++)
        {
            List<int> nums = Console.ReadLine().Split().Select(str => int.Parse(str)).ToList();
            nodes[nums[0] - 1].adjacentIds = nums.GetRange(2, nums[1]).Select(id => id - 1).ToList();
        }
    }

    // 幅優先探索
    static void Bfs(Node start)
    {
        start.dist = 0;
        queue.Enqueue(start);
        while (queue.Count() > 0)
        {
            Node node = queue.Dequeue();
            foreach (var id in node.adjacentIds)
            {
                if (nodes[id].dist == -1)
                {
                    nodes[id].dist = node.dist + 1;
                    queue.Enqueue(nodes[id]);
                }
            }
        }
    }

    // 出力
    static void Print()
    {
        for (int i = 0; i < n; i++)
        {
            System.Console.WriteLine(string.Format("{0} {1}", i + 1, nodes[i].dist));
        }
    }
}

