        static Queue<KeyValuePair<int, int>> q;
        static void Main(string[] args)
        {
            for (;;)
            {
                string line = Console.ReadLine();
                if (string.IsNullOrEmpty(line))
                {
                    break;
                }

                int n = int.Parse(line);
                graph = new int[n + 1, n + 1];
                q = new Queue<KeyValuePair<int, int>>();
                outArr = new int[n + 1];
                for (int i = 0; i < n; i++)
                {
                    int[] vertex = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
                    int u = vertex[0];
                    for (int k = 0; k < vertex[1]; k++)
                    {
                        graph[u, vertex[k + 2]] = 1;
                    }
                }

                for (int i = 0; i < outArr.Length; i++)
                {
                    outArr[i] = -1;
                }

                BreadthFirstSearch(1, 0);

                for(int i=1;i<outArr.Length;i++)
                {
                    Console.WriteLine("{0} {1}", i, outArr[i]);
                }
            }
        }

        static void BreadthFirstSearch(int id, int depth)
        {
            if (outArr[id] < 0)
            {
                outArr[id] = depth;
                for (int i = 1; i < graph.GetLength(1); i++)
                {
                    if (graph[id, i] > 0)
                    {
                        q.Enqueue(new KeyValuePair<int, int>(i, depth + 1));
                    }
                }

                while(q.Count>0)
                {
                    KeyValuePair<int, int> kvp = q.Dequeue();
                    BreadthFirstSearch(kvp.Key, kvp.Value);
                }
            }
        }
    }
}

using System;

public class Queue
{
  private int size, top, tail;
  private int[] array;
  public Queue(int size)
  {
    this.size = size + 1;
    array = new int[this.size];
    top = tail = 0;
  }
  public void Enqueue(int val)
  {
    if ((tail + 1) % this.size == this.top) throw new Exception("overflow error");
    this.array[tail] = val;
    if (this.tail + 1 >= this.size) this.tail = 0;
    else this.tail++;
  }
  public int Dequeue()
  {
    if (this.top == this.tail) throw new Exception("underflow error");
    int head = array[this.top];
    if (this.top + 1 >= this.size) this.top = 0;
    else this.top++;
    return head;
  }
  public bool IsEmpty()
  {
    return this.top == this.tail;
  }
}

public class Program
{
  private static int[,] graph;
  private static int[] distance;
  private static int graphSize;

  private static void BreadthFirsSearch()
  {
    Queue queue = new Queue(graphSize);
    try
    {
      queue.Enqueue(0);
      distance[0] = 0;
      while (!queue.IsEmpty())
      {
        int u = queue.Dequeue();
        for (int i = 0; i < graphSize; i++)
        {
          if (graph[u, i] == 0) continue;
          if (distance[i] != Int32.MaxValue) continue;
          distance[i] = distance[u] + 1;
          queue.Enqueue(i);
        }
      }
    }
    catch (Exception ex)
    {
      Console.WriteLine(ex.StackTrace.ToString());
    }
  }
  public static void Main()
  {
    int i, j, u, k, v;
    string[] ary;

    graphSize = int.Parse(Console.ReadLine());
    distance = new int[graphSize];
    for (i = 0; i < graphSize; i++) distance[i] = Int32.MaxValue;

    graph = new int[graphSize, graphSize];
    for (i = 0; i < graphSize; i++)
      for (j = 0; j < graphSize; j++)
        graph[i, j] = 0;

    for (i = 0; i < graphSize; i++)
    {
      ary = Console.ReadLine().Split(' ');
      u = int.Parse(ary[0]);
      k = int.Parse(ary[1]);
      for (j = 0; j < k; j++)
      {
        v = int.Parse(ary[2 + j]);
        graph[u - 1, v - 1] = 1;
      }
    }
    BreadthFirsSearch();

    for (i = 0; i < graphSize; i++)
    {
      Console.WriteLine("{0} {1}", i + 1, distance[i] == Int32.MaxValue ? -1 : distance[i]);
    }

  }
}

