namespace Graph_I
{
    class Breadth_First_Search
    {
        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            var G = new bool[n][];
            for (int i = 0; i < n; i++)
            {
                var token = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
                var row = token[0] - 1;
                G[row] = new bool[n];
                for (int j = 0; j < token[1]; j++)
                    G[row][token[2 + j] - 1] = true;
            }

            for (int i = 0; i < n; i++)
                Console.WriteLine("{0} {1}", i + 1, BreadthFirstSearch(G, 0, 0, i));
        }

        static int BreadthFirstSearch(bool[][] graph, int row, int dist, int destination)
        {
            if (row == destination) return dist;

            var d = -1;
            for (int i = 0; i < graph[row].Length; i++)
            {
                if (graph[row][i])
                {
                    var temp = BreadthFirstSearch(graph, i, dist + 1, destination);
                    if (temp == -1) continue;
                    if (d == -1 || temp < d) d = temp;
                }
            }

            return d;
        }
    }
}

