class Program
{
static long n = long.Parse(Console.ReadLine());
static long[] colors = new long[n];
static long[] distances = new long[n];
static Queue<long> que = new Queue<long>();//幅優先探索用のキュー
static long[,] nextMatrixes = new long[n,n];//隣接行列

	static void Main()
	{
		for(long i = 0; i < n; i++)
    {
      long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
      for(long j = 0; j < nums[1]; j++)
      {
        nextMatrixes[i,nums[j+2]-1] = 1;//隣接行列の作成
      }
    }

		BFS(0);//幅優先探索
	}

  static void BFS(long start)//幅優先探索
  {
    que.Enqueue(start);
    for(long i = 0; i < n; i++)
    {
      distances[i] = long.MaxValue;
    }
    distances[0] = 0;
    long poppedMemo = 0;
    while(que.Count > 0)
    {
      poppedMemo = que.Peek();
      que.Dequeue();

      for(long partnerNum = 0; partnerNum < n; partnerNum++)
      {
        if(nextMatrixes[poppedMemo, partnerNum] == 0) continue;
        if(distances[partnerNum] != long.MaxValue) continue;
        distances[partnerNum] = distances[poppedMemo] + 1;
        que.Enqueue(partnerNum);
      }
    }

    for(long i = 0; i < n; i++)
    {
      Console.WriteLine((i+1) + " "+ ((distances[i] != long.MaxValue) ? distances[i] : -1));
    }

  }

}

