namespace ConsoleApplication1
{
    class Program
    {
        static readonly int INFTY = int.MaxValue;

        static void Main(string[] args)
        {
            //StreamReader inputfile = new StreamReader("input.txt");
            int n = int.Parse(Console.ReadLine());
            int[,] table = new int[n, n];

            for (int i = 0; i < n; i++)
            {
                string[] input = Console.ReadLine().Split(' ');
                int u = int.Parse(input[0]) - 1;
                int k = int.Parse(input[1]);

                for (int j = 0; j < k; j++)
                {
                    int v = int.Parse(input[2 + j]) - 1;

                    table[u, v] = 1;
                }
            }

            Dijkstra(table, n);
        }

        static void Dijkstra(int[,] table, int n)
        {
            int i, minCost;
            int[] minCostArr = Enumerable.Repeat(INFTY, n).ToArray();
            bool[] isVisit = new bool[n];

            minCostArr[0] = 0;

            while (true)
            {
                minCost = INFTY;
                int u = -1;

                for (i = 0; i < n; i++)
                {
                    if (!isVisit[i] && minCost > minCostArr[i])
                    {
                        u = i;
                        minCost = minCostArr[i];
                    }
                }

                if (u == -1) break;

                isVisit[u] = true;

                for (i = 0; i < n; i++)
                {
                    int w = table[u, i];

                    if (w > 0)
                    {
                        int c = minCostArr[u] + w;

                        if (c < minCostArr[i])
                        {
                            minCostArr[i] = c;
                        }
                    }
                }
            }

            StringBuilder sb = new StringBuilder();
            for (i = 0; i < n; i++)
            {
                int temp = minCostArr[i] == INFTY ? -1 : minCostArr[i];
                sb.AppendLine((i + 1) + " " + temp);
            }
            Console.Write(sb);
        }
    }
}

