    @node = Array.new(n)
  end
  def breadth_first_search
    @node[0].d = 0
    q = [0]
    ii = 1
    loop do
      break if q.size == 0
      next_q = []
      q.each{|i|
        @node[i].child.each{|ch|
          if @node[ch-1].d < 0 then
            @node[ch-1].d = ii
            next_q << ch-1
          end
        }
      }
      q = next_q
      ii += 1
    end
  end
  def print
    @node.size.times{|i|
      puts "#{@node[i].val} #{@node[i].d}"
    }
  end
end

