const WHITE: u8 = 0;

const INFINITY: u64 = 10000000;

fn bfs(m: &Vec<Vec<u8>>, s: usize, color: &mut Vec<u8>, d: &mut Vec<u64>) {
    let mut q: VecDeque<u64> = VecDeque::new();
    q.push_back(s as u64);
    d[s] = 0;
    while q.len() > 0 {
        let u: usize = q.pop_front().unwrap() as usize;
        for v in 0..color.len() {
            if m[u][v] == 0 {
                continue;
            }
            if d[v] != INFINITY {
                continue;
            }
            d[v] = d[u] + 1;
            q.push_back(v as u64);
        }
    }
    for index in 0..d.len() {
        let number: i64;
        if d[index] == INFINITY {
            number = -1;
        } else {
            number = d[index] as i64;
        }
        println!("{} {}", index + 1, number);
    }
}

