use std::str::FromStr;
use std::io::*;
use std::collections::*;
use std::cmp::*;

struct Scanner<I: Iterator<Item = char>> {
    iter: std::iter::Peekable<I>,
}

macro_rules! exit {
    () => {{
        exit!(0)
    }};
    ($code:expr) => {{
        if cfg!(local) {
            writeln!(std::io::stderr(), "===== Terminated =====")
                .expect("failed printing to stderr");
        }
        std::process::exit($code);
    }}
}

impl<I: Iterator<Item = char>> Scanner<I> {
    pub fn new(iter: I) -> Scanner<I> {
        Scanner {
            iter: iter.peekable(),
        }
    }

    pub fn safe_get_token(&mut self) -> Option<String> {
        let token = self.iter
            .by_ref()
            .skip_while(|c| c.is_whitespace())
            .take_while(|c| !c.is_whitespace())
            .collect::<String>();
        if token.is_empty() {
            None
        } else {
            Some(token)
        }
    }

    pub fn token(&mut self) -> String {
        self.safe_get_token().unwrap_or_else(|| exit!())
    }

    pub fn get<T: FromStr>(&mut self) -> T {
        self.token().parse::<T>().unwrap_or_else(|_| exit!())
    }

    pub fn vec<T: FromStr>(&mut self, len: usize) -> Vec<T> {
        (0..len).map(|_| self.get()).collect()
    }

    pub fn mat<T: FromStr>(&mut self, row: usize, col: usize) -> Vec<Vec<T>> {
        (0..row).map(|_| self.vec(col)).collect()
    }

    pub fn char(&mut self) -> char {
        self.iter.next().unwrap_or_else(|| exit!())
    }

    pub fn chars(&mut self) -> Vec<char> {
        self.get::<String>().chars().collect()
    }

    pub fn line(&mut self) -> String {
        if self.peek().is_some() {
            self.iter
                .by_ref()
                .take_while(|&c| !(c == '\n' || c == '\r'))
                .collect::<String>()
        } else {
            exit!();
        }
    }

    pub fn peek(&mut self) -> Option<&char> {
        self.iter.peek()
    }
}

fn main() {
    let cin = stdin();
    let cin = cin.lock();
    let mut sc = Scanner::new(cin.bytes().map(|c| c.unwrap() as char));
    let n: usize = sc.get();
    let mut adj = vec![Vec::new(); n];
    for _ in 0..n {
        let u = sc.get::<usize>() - 1;
        let k: usize = sc.get();
        for _ in 0..k {
            let v = sc.get::<usize>() - 1;
            adj[u].push(v);
        }
    }
    let mut dist = vec![-1; n];
    dist[0] = 0;
    let mut q = VecDeque::new();
    q.push_front(0);
    while let Some(i) = q.pop_back() {
        let cur = dist[i];

        for &n in &adj[i] {
            if dist[n] != -1 { continue; }

            dist[n] = cur + 1;
            q.push_front(n);
        }
    }

    for i in 0..n {
        println!("{} {}", i+1, dist[i]);
    }
}

use std::collections::VecDeque;
use std::io::Read;

fn read<T: std::str::FromStr>() -> T {
    let stdin = std::io::stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

type Graph = Vec<Vec<usize>>;

fn bfs(g: &Graph, s: usize) -> (Vec<Option<usize>>, Vec<Option<usize>>) {
    let n = g.len();
    let mut dist = vec![None; n];
    let mut prev = vec![None; n];
    let mut pool = VecDeque::new();

    dist[s] = Some(0);
    pool.push_back(s);

    while let Some(v) = pool.pop_front() {
        for &w in g[v].iter() {
            if dist[w].is_some() {
                continue;
            }
            dist[w] = dist[v].map(|x| x + 1);
            prev[w] = Some(v);
            pool.push_back(w);
        }
    }
    (dist, prev)
}

fn main() {
    let n: usize = read();

    let mut g = vec![vec![]; n];
    for _ in 0..n {
        let u: usize = read();
        let k: usize = read();
        for _ in 0..k {
            let v: usize = read();
            g[u - 1].push(v - 1);
        }
    }

    let (dist, _) = bfs(&g, 0);

    for (v, &d) in dist.iter().enumerate() {
        if let Some(d) = d {
            println!("{} {}", v + 1, d);
        } else {
            println!("{} {}", v + 1, -1);
        }
    }
}

use std::io;
use std::cmp;
use std::collections::VecDeque;

fn main() {
    let n = read_one::<usize>();
    let mut g = Vec::new();
    for _ in 0..n {
        let vs = read::<usize>()[2..].iter()
            .map(|v| v - 1)
            .collect::<Vec<_>>();
        g.push(vs);
    }

    let mut cost = vec![!0; n];
    let mut arrived = vec![false; n];
    let mut q = VecDeque::new();
    q.push_back((0, 0));

    while let Some((v, p)) = q.pop_front() {
        arrived[v] = true;
        cost[v] = cmp::min(cost[v], 1usize.wrapping_add(cost[p]));

        for &u in &g[v] {
            if u == p || arrived[u] { continue; }
            q.push_back((u, v));
        }
    }

    for (i, &c) in cost.iter().enumerate() {
        print!("{} ", i + 1);
        println!("{}", if arrived[i] { c as isize } else { -1 });
    }
}

#[allow(unused)]
fn read<T>() -> Vec<T>
where
    T: std::str::FromStr,
    T::Err: std::fmt::Debug {

    let mut buf = String::new();
    io::stdin().read_line(&mut buf).unwrap();
    buf.split_whitespace()
        .map(|s| s.trim().parse().unwrap())
        .collect()
}


#[allow(unused)]
fn read_one<T>() -> T
where
    T: std::str::FromStr,
    T::Err: std::fmt::Debug {

    let mut buf = String::new();
    io::stdin().read_line(&mut buf).unwrap();
    buf.trim().parse().unwrap()
}

use std::io;
use std::io::BufRead;
use std::collections::VecDeque;

struct Graph {
    n: usize,
    adj: Vec<Vec<usize>>,
}

fn read_graph() -> Graph {
    let stdin = io::stdin();
    let lock = stdin.lock();
    let mut lines = lock.lines();
    let n = lines.next().unwrap().unwrap().parse().unwrap();
    let mut adj = Vec::new();

    for line in lines {
        let parsed: Vec<usize> = line
            .unwrap()
            .split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect();

        adj.push(parsed[2..].iter().map(|x| x - 1).collect());
    }

    Graph { n, adj }
}

fn main() {
    let graph = read_graph();

    let mut d = vec![-1; graph.n];
    let mut q = VecDeque::new();

    d[0] = 0;
    q.push_back(0);

    while let Some(i) = q.pop_front() {
        for &j in graph.adj[i].iter() {
            if d[j] < 0 {
                d[j] = d[i] + 1;
                q.push_back(j);
            }
        }
    }

    for i in 0..(graph.n) {
        println!("{} {}", i + 1, d[i]);
    }
}

use std::io::{BufRead, Write, stdin, stdout};
use std::collections::VecDeque;

fn main() {
    let stdin = stdin();
    let reader = stdin.lock();
    let writer = stdout();
    solve(reader, writer);
}

fn solve<R, W>(mut reader: R, mut writer: W)
where
    R: BufRead,
    W: Write,
{
    let mut buf = String::new();
    reader.read_to_string(&mut buf).unwrap();
    let mut input = buf.split_whitespace();

    let n: usize = input.next().unwrap().parse().unwrap();
    let mut graph: Vec<Vec<usize>> = vec![Vec::new(); n];
    for _ in 0..n {
        let u: usize = input.next().unwrap().parse().unwrap();
        let k: usize = input.next().unwrap().parse().unwrap();
        for _ in 0..k {
            graph[u - 1].push(input.next().unwrap().parse::<usize>().unwrap() - 1);
        }
    }

    let mut d: Vec<isize> = vec![-1; n];
    d[0] = 0;
    let mut queue: VecDeque<usize> = VecDeque::new();
    queue.push_back(0);
    while !queue.is_empty() {
        let u = queue.pop_front().unwrap();
        let nexts = &graph[u];
        for &n in nexts {
            if d[n] == -1 {
                d[n] = d[u] + 1;
                queue.push_back(n);
            }
        }
    }

    for i in 0..n {
        writeln!(&mut writer, "{} {}", i + 1, d[i]).unwrap();
    }
}
